-- realtime: the dashboard listens to monitor01_view; the month turnover is streamed too (small, only changed rows). The MOVEMENTS are not streamed (a posted plan has thousands of rows).
DO $$
DECLARE
  v_all boolean; v_t text;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all THEN
    FOREACH v_t IN ARRAY ARRAY['monitor01_view', 'project_status_month_turnover'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_t) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_t);
      END IF;
    END LOOP;
  END IF;
END $$;


-- ---- the register functions and the fresh numbers of some tasks (the ONE definition of every number: the worker, monitor01_verify and the tests use it) ----
-- ---- the register functions: ONE rule for every document type ---------------------------------------------------------------------------------------------------------------------
-- unregister: the movements of a registrator (a posted document taken back / the plan of a task rewritten)
CREATE OR REPLACE FUNCTION public.project_status_unregister(p_registrator uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v integer;
BEGIN
  DELETE FROM public.project_status_movements s WHERE s."rowRegistratorGUID" = p_registrator;
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.project_status_unregister(uuid) FROM PUBLIC, anon, authenticated;


-- the PLAN of some tasks: the posted movements of task_line_plan_movements (planMovementStatus) become 'plan' movements, registrator = the task (type projectTask). Rewritten by the worker for the tasks of its batch
-- (a line edit, a re-post, a rename ... all queue the task), so the register is never older than one tick. A task whose plan did not change is only READ (a fingerprint), never written.
CREATE OR REPLACE FUNCTION public.project_status_register_plan(p_tasks uuid[]) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v integer := 0; v_changed uuid[];
BEGIN
  -- only the tasks whose plan CHANGED are rewritten: a fingerprint of the plan rows of the source and of the register is compared (reading is cheap, writing 5 indexes is not)
  WITH src AS (
    SELECT m."rowOwnerGUID" AS task, m."rowParentGUID" AS line, m."rowPeriodDatetime" AS moment,
           ROW(m."rowParentGUID", m."rowPeriodDatetime", COALESCE(m."periodDay", ((m."rowPeriodDatetime" + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date), l."rowParentGUID",
               COALESCE(l."rowJSON"->>'resourceRoleItem', ''), COALESCE(l."rowJSON"->>'measureUnitTaskLine', ''), NULLIF(l."rowJSON"->>'businessUnitTaskLine', ''),
               NULLIF(CASE WHEN l."rowParentGUID" = 'timeGenus' THEN l."rowJSON"->>'taskResourceContract' ELSE l."rowJSON"->>'taskLinePartnerContract' END, ''),
               COALESCE(m."qtyTaskLine", 0)::numeric(18,2), COALESCE(m."sumForBudget", 0)::numeric(18,2), COALESCE(m."sumForContract", 0)::numeric(18,2), COALESCE(m."sumForAccounting", 0)::numeric(18,2),
               COALESCE(m."vatForBudget", 0)::numeric(18,2), COALESCE(m."vatInCostForBudget", 0)::numeric(18,2))::text AS t
      FROM public.task_line_plan_movements m
      JOIN public.task_line_table l ON l."rowGUID" = m."rowParentGUID"
     WHERE m."rowOwnerGUID" = ANY (p_tasks) AND m."planMovementStatus" AND l."rowParentGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus', 'revenueGenus')
  ), f_src AS (
    SELECT task, md5(string_agg(t, '|' ORDER BY line, moment)) AS fp FROM src GROUP BY task
  ), f_reg AS (
    SELECT s."rowOwnerGUID" AS task,
           md5(string_agg(ROW(s."rowProjectTaskLineGUID", s."rowTurnoverMoment", s."rowTurnoverDay", s."genusGUID", s."resourceRoleGUID", s."measureUnit", s."businessUnitGUID", s."contractGUID",
                              s."qtyProjectStatus", s."sumForBudget", s."sumForContract", s."sumForAccounting", s."vatForBudget", s."vatInCostForBudget")::text, '|' ORDER BY s."rowProjectTaskLineGUID", s."rowTurnoverMoment")) AS fp
      FROM public.project_status_movements s
     WHERE s."rowMovementKind" = 'plan' AND s."rowOwnerGUID" = ANY (p_tasks)
     GROUP BY s."rowOwnerGUID"
  )
  SELECT COALESCE(array_agg(x.task), ARRAY[]::uuid[]) INTO v_changed FROM (
    SELECT fs.task FROM f_src fs LEFT JOIN f_reg fr ON fr.task = fs.task WHERE fr.fp IS DISTINCT FROM fs.fp
    UNION SELECT fr.task FROM f_reg fr WHERE NOT EXISTS (SELECT 1 FROM f_src fs WHERE fs.task = fr.task)) x;
  IF cardinality(v_changed) = 0 THEN
    RETURN 0;
  END IF;
  DELETE FROM public.project_status_movements s WHERE s."rowMovementKind" = 'plan' AND s."rowOwnerGUID" = ANY (v_changed);
  INSERT INTO public.project_status_movements ("rowMovementKind", "rowTurnoverMoment", "rowTurnoverDay", "rowRegistratorGUID", "rowRegistratorType", "rowProjectTaskLineGUID", "rowProjectGUID", "rowOwnerGUID", "rowOwnerUserGUID",
         "genusGUID", "resourceRoleGUID", "measureUnit", "businessUnitGUID", "contractGUID", "qtyProjectStatus", "sumForBudget", "sumForContract", "sumForAccounting", "vatForBudget", "vatInCostForBudget")
  SELECT 'plan', m."rowPeriodDatetime", COALESCE(m."periodDay", ((m."rowPeriodDatetime" + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date),
         m."rowOwnerGUID", 'projectTask', m."rowParentGUID", m."rowProjectGUID", m."rowOwnerGUID", p."rowOwnerGUID",
         l."rowParentGUID", COALESCE(l."rowJSON"->>'resourceRoleItem', ''), COALESCE(l."rowJSON"->>'measureUnitTaskLine', ''),
         NULLIF(l."rowJSON"->>'businessUnitTaskLine', ''),
         NULLIF(CASE WHEN l."rowParentGUID" = 'timeGenus' THEN l."rowJSON"->>'taskResourceContract' ELSE l."rowJSON"->>'taskLinePartnerContract' END, ''),
         COALESCE(m."qtyTaskLine", 0), COALESCE(m."sumForBudget", 0), COALESCE(m."sumForContract", 0), COALESCE(m."sumForAccounting", 0), COALESCE(m."vatForBudget", 0), COALESCE(m."vatInCostForBudget", 0)
    FROM public.task_line_plan_movements m
    JOIN public.task_line_table l ON l."rowGUID" = m."rowParentGUID"
    JOIN public.project_table p ON p."rowGUID" = m."rowProjectGUID"
   WHERE m."rowOwnerGUID" = ANY (v_changed) AND m."planMovementStatus" AND l."rowParentGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus', 'revenueGenus');
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.project_status_register_plan(uuid[]) FROM PUBLIC, anon, authenticated;


-- a POSTED fact document: its lines become 'used' movements, registrator = the document (type taskFactHeader). A document that is not posted only loses its movements.
CREATE OR REPLACE FUNCTION public.project_status_register_fact(p_header uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v integer := 0;
BEGIN
  DELETE FROM public.project_status_movements s WHERE s."rowRegistratorGUID" = p_header;
  INSERT INTO public.project_status_movements ("rowMovementKind", "rowTurnoverMoment", "rowTurnoverDay", "rowRegistratorGUID", "rowRegistratorType", "rowProjectTaskLineGUID", "rowProjectGUID", "rowOwnerGUID", "rowOwnerUserGUID",
         "genusGUID", "resourceRoleGUID", "measureUnit", "businessUnitGUID", "qtyProjectStatus", "sumForBudget", "sumForContract", "sumForAccounting",
         "vatForContract", "vatForBudget", "vatInCostForBudget", "vatForAccounting", "vatInCostForAccounting", "rowJSON")
  SELECT 'used', f."rowPeriodDatetime", f."periodDay", f."rowHeaderGUID", 'taskFactHeader', f."taskLineGUID", f."rowProjectGUID", f."rowOwnerGUID", p."rowOwnerGUID",
         f."genusGUID", COALESCE(f."rowJSON"->>'resourceRoleItem', ''), COALESCE(f."rowJSON"->>'measureUnitTaskLine', ''), NULLIF(f."rowJSON"->>'businessUnitTaskLine', ''),
         COALESCE(f."qtyForContract", 0), COALESCE(f."sumForBudget", 0), COALESCE(f."sumForContract", 0), COALESCE(f."sumForAccounting", 0),
         COALESCE(f."vatForContract", 0), COALESCE(f."vatForBudget", 0), COALESCE(f."vatInCostForBudget", 0), COALESCE(f."vatForAccounting", 0), COALESCE(f."vatInCostForAccounting", 0),
         -- ownCost (PART 33): a cost line with NO vendor can only be a fact input: its cost is never invoiced and counts for ROI4
         jsonb_build_object('ownCost', f."genusGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus') AND NOT public.pm_line_has_vendor(f."genusGUID", f."rowJSON"))
    FROM public.task_fact_usage_timeline f
    JOIN public.task_fact_header h ON h."rowGUID" = f."rowHeaderGUID"
    JOIN public.project_table p ON p."rowGUID" = f."rowProjectGUID"
   WHERE f."rowHeaderGUID" = p_header AND COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted'
     AND f."genusGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus', 'revenueGenus');
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.project_status_register_fact(uuid) FROM PUBLIC, anon, authenticated;


-- the fresh turnover of some tasks, summed from the register (the ONE definition: the worker, monitor01_verify and the tests use it)
DROP FUNCTION IF EXISTS public.project_status_fresh_turnover(uuid[]);

CREATE OR REPLACE FUNCTION public.project_status_fresh_turnover(p_tasks uuid[])
RETURNS TABLE ("rowOwnerGUID" uuid, "genusGUID" text, "resourceRoleGUID" text, "measureUnit" text, "rowTurnoverMonth" date, "rowProjectGUID" uuid, "rowOwnerUserGUID" uuid,
               "qtyPlan" numeric,
               "sumForBudgetPlan" numeric,
               "sumForContractPlan" numeric,
               "sumForAccountingPlan" numeric,
               "qtyPlanContracted" numeric,
               "qtyUsed" numeric,
               "sumForBudgetUsed" numeric,
               "sumForContractUsed" numeric,
               "sumForAccountingUsed" numeric,
               "qtyInvoiced" numeric,
               "sumForBudgetInvoiced" numeric,
               "sumForContractInvoiced" numeric,
               "sumForAccountingInvoiced" numeric,
               "vatForContractInvoiced" numeric,
               "vatForAccountingInvoiced" numeric,
               "qtyOrdered" numeric,
               "sumForBudgetOrdered" numeric,
               "sumForContractOrdered" numeric,
               "sumForAccountingOrdered" numeric,
               "vatForContractOrdered" numeric,
               "vatForAccountingOrdered" numeric,
               "qtyReceived" numeric,
               "sumForBudgetReceived" numeric,
               "sumForContractReceived" numeric,
               "sumForAccountingReceived" numeric,
               "vatForContractReceived" numeric,
               "vatForAccountingReceived" numeric,
               "qtySold" numeric,
               "sumForBudgetSold" numeric,
               "vatForBudgetPlan" numeric, "vatInCostForBudgetPlan" numeric, "vatForBudgetInvoiced" numeric, "vatInCostForBudgetInvoiced" numeric, "vatForBudgetSold" numeric,
               "lineCount" integer, "documentCount" integer)
LANGUAGE sql STABLE SET search_path = public, extensions AS $$
  SELECT s."rowOwnerGUID", s."genusGUID", s."resourceRoleGUID", s."measureUnit", s."rowTurnoverMonth", s."rowProjectGUID", s."rowOwnerUserGUID",
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."sumForContract")        FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."sumForAccounting")      FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'plan' AND s."contractGUID" IS NOT NULL), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'used'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'used'), 0),
         COALESCE(SUM(s."sumForContract")        FILTER (WHERE s."rowMovementKind" = 'used'), 0),
         COALESCE(SUM(s."sumForAccounting")      FILTER (WHERE s."rowMovementKind" = 'used'), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."sumForContract")        FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."sumForAccounting")      FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."vatForContract")        FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."vatForAccounting")      FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."sumForContract")        FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."sumForAccounting")      FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."vatForContract")        FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."vatForAccounting")      FILTER (WHERE s."rowMovementKind" = 'ordered'), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."sumForContract")        FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."sumForAccounting")      FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."vatForContract")        FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."vatForAccounting")      FILTER (WHERE s."rowMovementKind" = 'received'), 0),
         COALESCE(SUM(s."qtyProjectStatus")      FILTER (WHERE s."rowMovementKind" = 'sold'), 0),
         COALESCE(SUM(s."sumForBudget")          FILTER (WHERE s."rowMovementKind" = 'sold'), 0),
         COALESCE(SUM(s."vatForBudget")          FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."vatInCostForBudget")    FILTER (WHERE s."rowMovementKind" = 'plan'), 0),
         COALESCE(SUM(s."vatForBudget")          FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."vatInCostForBudget")    FILTER (WHERE s."rowMovementKind" = 'invoiced'), 0),
         COALESCE(SUM(s."vatForBudget")          FILTER (WHERE s."rowMovementKind" = 'sold'), 0),
         COALESCE(NULLIF((count(DISTINCT s."rowProjectTaskLineGUID") FILTER (WHERE s."rowMovementKind" = 'plan'))::integer, 0), (count(*) FILTER (WHERE s."rowMovementKind" = 'used'))::integer, 0),
         (count(DISTINCT s."rowRegistratorGUID") FILTER (WHERE s."rowMovementKind" IN ('used', 'invoiced', 'ordered', 'received', 'sold')))::integer
    FROM public.project_status_movements s
   -- the Revenue (Deliverable) genus is in the report ONLY through the posted customer invoices ('sold'): no plan, no Contracted, no Budget of the revenue lines (decision Q4 stays for those)
   WHERE s."rowOwnerGUID" = ANY (p_tasks) AND (s."genusGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus') OR s."rowMovementKind" = 'sold')
   GROUP BY 1, 2, 3, 4, 5, 6, 7
$$;


-- (the result gained sumForBudget and qtyUsed$$;

-- (the result gained sumForBudget and qtyUsed: a function cannot change its result type in place)
DROP FUNCTION IF EXISTS public.monitor01_fresh_rows(uuid[]);

CREATE OR REPLACE FUNCTION public.monitor01_fresh_rows(p_tasks uuid[])
RETURNS TABLE ("rowOwnerGUID" uuid, "genusGUID" text, "resourceRoleGUID" text, "measureUnit" text, "periodMonth" date,
               "rowProjectGUID" uuid, "rowOrganizationGUID" text, "rowOwnerUserGUID" uuid, "projectName" text, "taskName" text, "resourceRoleName" text,
               "qtyPlanned" numeric, "qtyContracted" numeric, "sumForBudget" numeric, "qtyUsed" numeric, "qtyVendorInvoiced" numeric, "sumVendorInvoiced" numeric, "qtyOrdered" numeric, "qtyReceived" numeric, "qtyCustomerInvoiced" numeric, "sumCustomerInvoiced" numeric, "vatBudget" numeric, "vatInCostBudget" numeric, "vatVendorInvoiced" numeric, "vatInCostVendorInvoiced" numeric, "vatCustomerInvoiced" numeric, "lineCount" integer, "hasStalePlan" boolean)
LANGUAGE sql STABLE SET search_path = public, extensions AS $$
  -- the report row = the turnover of the register + the names + "plan not posted after a change" (the line says so)
  WITH st AS (
    SELECT s."rowOwnerGUID" AS task, s."genusGUID" AS genus, s."resourceRoleGUID" AS role, s."measureUnit" AS unit, s."rowTurnoverMonth" AS month,
           bool_or(COALESCE((l."rowJSON"->>'taskIsPosted')::boolean, false) = false) AS stale
      FROM public.project_status_movements s
      JOIN public.task_line_table l ON l."rowGUID" = s."rowProjectTaskLineGUID"
     WHERE s."rowMovementKind" = 'plan' AND s."rowOwnerGUID" = ANY (p_tasks) AND s."genusGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus')
     GROUP BY 1, 2, 3, 4, 5
  )
  SELECT t."rowOwnerGUID", t."genusGUID", t."resourceRoleGUID", t."measureUnit", t."rowTurnoverMonth",
         p."rowGUID", p."rowParentGUID", p."rowOwnerGUID",
         COALESCE(p."rowJSON"->>'name', p."rowJSON"->>'title', ''), COALESCE(tk."rowJSON"->>'taskDescription', ''), COALESCE(r."rowJSON"->>'title', ''),
         t."qtyPlan", t."qtyPlanContracted", t."sumForBudgetPlan", t."qtyUsed", t."qtyInvoiced", t."sumForBudgetInvoiced", t."qtyOrdered", t."qtyReceived", t."qtySold", t."sumForBudgetSold", t."vatForBudgetPlan", t."vatInCostForBudgetPlan", t."vatForBudgetInvoiced", t."vatInCostForBudgetInvoiced", t."vatForBudgetSold", t."lineCount", COALESCE(st.stale, false)
    FROM public.project_status_fresh_turnover(p_tasks) t
    JOIN public.project_task_table tk ON tk."rowGUID" = t."rowOwnerGUID"
    JOIN public.project_table p ON p."rowGUID" = tk."projectGUID"
    LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(t."resourceRoleGUID", '')
    LEFT JOIN st ON st.task = t."rowOwnerGUID" AND st.genus = t."genusGUID" AND st.role = t."resourceRoleGUID" AND st.unit = t."measureUnit" AND st.month = t."rowTurnoverMonth"
   WHERE t."qtyPlan" <> 0 OR t."qtyUsed" <> 0 OR t."qtyInvoiced" <> 0 OR t."sumForBudgetInvoiced" <> 0 OR t."qtyOrdered" <> 0 OR t."qtyReceived" <> 0 OR t."qtySold" <> 0 OR t."sumForBudgetSold" <> 0 OR t."sumForBudgetPlan" <> 0 OR t."lineCount" > 0
$$;



-- ---- the worker -----------------------------------------------------------------------------------------------------------------------------------------------
-- apply ONE group of tasks: step 1 the fact sums, step 2 the view; ONLY the rows whose numbers (or names) changed are written. Returns rows upserted and deleted.
CREATE OR REPLACE FUNCTION public.monitor01_apply(p_tasks uuid[], OUT p_upserted integer, OUT p_deleted integer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_u integer; v_d integer; v_fu integer; v_fd integer;
BEGIN
  -- step 0: the PLAN of these tasks is registered again from the posted plan movements (the register is the source of the numbers)
  PERFORM public.project_status_register_plan(p_tasks);

  -- step 1: project_status_month_turnover = the register summed; only changed rows are written
  WITH fresh AS MATERIALIZED (SELECT * FROM public.project_status_fresh_turnover(p_tasks)),
       up AS (
         INSERT INTO public.project_status_month_turnover AS t ("rowOwnerGUID", "genusGUID", "resourceRoleGUID", "measureUnit", "rowTurnoverMonth", "rowProjectGUID", "rowOwnerUserGUID", "qtyPlan", "sumForBudgetPlan", "sumForContractPlan", "sumForAccountingPlan", "vatForBudgetPlan", "vatInCostForBudgetPlan", "qtyPlanContracted", "qtyUsed", "sumForBudgetUsed", "sumForContractUsed", "sumForAccountingUsed", "qtyInvoiced", "sumForBudgetInvoiced", "sumForContractInvoiced", "sumForAccountingInvoiced", "vatForContractInvoiced", "vatForAccountingInvoiced", "qtyOrdered", "sumForBudgetOrdered", "sumForContractOrdered", "sumForAccountingOrdered", "vatForContractOrdered", "vatForAccountingOrdered", "qtyReceived", "sumForBudgetReceived", "sumForContractReceived", "sumForAccountingReceived", "vatForContractReceived", "vatForAccountingReceived", "qtySold", "sumForBudgetSold", "lineCount", "documentCount")
         SELECT f."rowOwnerGUID", f."genusGUID", f."resourceRoleGUID", f."measureUnit", f."rowTurnoverMonth", f."rowProjectGUID", f."rowOwnerUserGUID", f."qtyPlan", f."sumForBudgetPlan", f."sumForContractPlan", f."sumForAccountingPlan", f."vatForBudgetPlan", f."vatInCostForBudgetPlan", f."qtyPlanContracted", f."qtyUsed", f."sumForBudgetUsed", f."sumForContractUsed", f."sumForAccountingUsed", f."qtyInvoiced", f."sumForBudgetInvoiced", f."sumForContractInvoiced", f."sumForAccountingInvoiced", f."vatForContractInvoiced", f."vatForAccountingInvoiced", f."qtyOrdered", f."sumForBudgetOrdered", f."sumForContractOrdered", f."sumForAccountingOrdered", f."vatForContractOrdered", f."vatForAccountingOrdered", f."qtyReceived", f."sumForBudgetReceived", f."sumForContractReceived", f."sumForAccountingReceived", f."vatForContractReceived", f."vatForAccountingReceived", f."qtySold", f."sumForBudgetSold", f."lineCount", f."documentCount" FROM fresh f
         ON CONFLICT ("rowOwnerGUID", "genusGUID", "resourceRoleGUID", "measureUnit", "rowTurnoverMonth") DO UPDATE
           SET "rowProjectGUID" = EXCLUDED."rowProjectGUID", "rowOwnerUserGUID" = EXCLUDED."rowOwnerUserGUID", "qtyPlan" = EXCLUDED."qtyPlan", "sumForBudgetPlan" = EXCLUDED."sumForBudgetPlan", "sumForContractPlan" = EXCLUDED."sumForContractPlan", "sumForAccountingPlan" = EXCLUDED."sumForAccountingPlan", "vatForBudgetPlan" = EXCLUDED."vatForBudgetPlan", "vatInCostForBudgetPlan" = EXCLUDED."vatInCostForBudgetPlan", "qtyPlanContracted" = EXCLUDED."qtyPlanContracted", "qtyUsed" = EXCLUDED."qtyUsed", "sumForBudgetUsed" = EXCLUDED."sumForBudgetUsed", "sumForContractUsed" = EXCLUDED."sumForContractUsed", "sumForAccountingUsed" = EXCLUDED."sumForAccountingUsed", "qtyInvoiced" = EXCLUDED."qtyInvoiced", "sumForBudgetInvoiced" = EXCLUDED."sumForBudgetInvoiced", "sumForContractInvoiced" = EXCLUDED."sumForContractInvoiced", "sumForAccountingInvoiced" = EXCLUDED."sumForAccountingInvoiced", "vatForContractInvoiced" = EXCLUDED."vatForContractInvoiced", "vatForAccountingInvoiced" = EXCLUDED."vatForAccountingInvoiced", "qtyOrdered" = EXCLUDED."qtyOrdered", "sumForBudgetOrdered" = EXCLUDED."sumForBudgetOrdered", "sumForContractOrdered" = EXCLUDED."sumForContractOrdered", "sumForAccountingOrdered" = EXCLUDED."sumForAccountingOrdered", "vatForContractOrdered" = EXCLUDED."vatForContractOrdered", "vatForAccountingOrdered" = EXCLUDED."vatForAccountingOrdered", "qtyReceived" = EXCLUDED."qtyReceived", "sumForBudgetReceived" = EXCLUDED."sumForBudgetReceived", "sumForContractReceived" = EXCLUDED."sumForContractReceived", "sumForAccountingReceived" = EXCLUDED."sumForAccountingReceived", "vatForContractReceived" = EXCLUDED."vatForContractReceived", "vatForAccountingReceived" = EXCLUDED."vatForAccountingReceived", "qtySold" = EXCLUDED."qtySold", "sumForBudgetSold" = EXCLUDED."sumForBudgetSold", "lineCount" = EXCLUDED."lineCount", "documentCount" = EXCLUDED."documentCount", "updated_at" = NOW()
         WHERE (t."rowProjectGUID", t."rowOwnerUserGUID", t."qtyPlan", t."sumForBudgetPlan", t."sumForContractPlan", t."sumForAccountingPlan", t."vatForBudgetPlan", t."vatInCostForBudgetPlan", t."qtyPlanContracted", t."qtyUsed", t."sumForBudgetUsed", t."sumForContractUsed", t."sumForAccountingUsed", t."qtyInvoiced", t."sumForBudgetInvoiced", t."sumForContractInvoiced", t."sumForAccountingInvoiced", t."vatForContractInvoiced", t."vatForAccountingInvoiced", t."qtyOrdered", t."sumForBudgetOrdered", t."sumForContractOrdered", t."sumForAccountingOrdered", t."vatForContractOrdered", t."vatForAccountingOrdered", t."qtyReceived", t."sumForBudgetReceived", t."sumForContractReceived", t."sumForAccountingReceived", t."vatForContractReceived", t."vatForAccountingReceived", t."qtySold", t."sumForBudgetSold", t."lineCount", t."documentCount")
               IS DISTINCT FROM (EXCLUDED."rowProjectGUID", EXCLUDED."rowOwnerUserGUID", EXCLUDED."qtyPlan", EXCLUDED."sumForBudgetPlan", EXCLUDED."sumForContractPlan", EXCLUDED."sumForAccountingPlan", EXCLUDED."vatForBudgetPlan", EXCLUDED."vatInCostForBudgetPlan", EXCLUDED."qtyPlanContracted", EXCLUDED."qtyUsed", EXCLUDED."sumForBudgetUsed", EXCLUDED."sumForContractUsed", EXCLUDED."sumForAccountingUsed", EXCLUDED."qtyInvoiced", EXCLUDED."sumForBudgetInvoiced", EXCLUDED."sumForContractInvoiced", EXCLUDED."sumForAccountingInvoiced", EXCLUDED."vatForContractInvoiced", EXCLUDED."vatForAccountingInvoiced", EXCLUDED."qtyOrdered", EXCLUDED."sumForBudgetOrdered", EXCLUDED."sumForContractOrdered", EXCLUDED."sumForAccountingOrdered", EXCLUDED."vatForContractOrdered", EXCLUDED."vatForAccountingOrdered", EXCLUDED."qtyReceived", EXCLUDED."sumForBudgetReceived", EXCLUDED."sumForContractReceived", EXCLUDED."sumForAccountingReceived", EXCLUDED."vatForContractReceived", EXCLUDED."vatForAccountingReceived", EXCLUDED."qtySold", EXCLUDED."sumForBudgetSold", EXCLUDED."lineCount", EXCLUDED."documentCount")
         RETURNING 1),
       del AS (
         DELETE FROM public.project_status_month_turnover t
          WHERE t."rowOwnerGUID" = ANY (p_tasks)
            AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f."rowOwnerGUID" = t."rowOwnerGUID" AND f."genusGUID" = t."genusGUID" AND f."resourceRoleGUID" = t."resourceRoleGUID"
                                                    AND f."measureUnit" = t."measureUnit" AND f."rowTurnoverMonth" = t."rowTurnoverMonth")
         RETURNING 1)
  SELECT (SELECT count(*) FROM up), (SELECT count(*) FROM del) INTO v_fu, v_fd;

  -- step 2: monitor01_view (qtyUsed = the quantity of the POSTED fact documents; qtyVendorInvoiced = the quantity of the POSTED vendor invoices; qtyOrdered = the POSTED purchase orders; qtyReceived = the quantity of the POSTED product receipts)
  WITH fresh AS MATERIALIZED (SELECT * FROM public.monitor01_fresh_rows(p_tasks)),
       up AS (
         INSERT INTO public.monitor01_view AS v ("rowOwnerGUID", "genusGUID", "resourceRoleGUID", "measureUnit", "periodMonth", "rowProjectGUID", "rowOrganizationGUID", "rowOwnerUserGUID",
                                                "projectName", "taskName", "resourceRoleName", "qtyPlanned", "qtyContracted", "sumForBudget", "qtyUsed", "qtyVendorInvoiced", "sumVendorInvoiced", "qtyOrdered", "qtyReceived", "qtyCustomerInvoiced", "sumCustomerInvoiced", "vatBudget", "vatInCostBudget", "vatVendorInvoiced", "vatInCostVendorInvoiced", "vatCustomerInvoiced", "lineCount", "hasStalePlan")
         SELECT f."rowOwnerGUID", f."genusGUID", f."resourceRoleGUID", f."measureUnit", f."periodMonth", f."rowProjectGUID", f."rowOrganizationGUID", f."rowOwnerUserGUID",
                f."projectName", f."taskName", f."resourceRoleName", f."qtyPlanned", f."qtyContracted", f."sumForBudget", f."qtyUsed", f."qtyVendorInvoiced", f."sumVendorInvoiced", f."qtyOrdered", f."qtyReceived", f."qtyCustomerInvoiced", f."sumCustomerInvoiced", f."vatBudget", f."vatInCostBudget", f."vatVendorInvoiced", f."vatInCostVendorInvoiced", f."vatCustomerInvoiced", f."lineCount", f."hasStalePlan" FROM fresh f
         ON CONFLICT ("rowOwnerGUID", "genusGUID", "resourceRoleGUID", "measureUnit", "periodMonth") DO UPDATE
           SET "rowProjectGUID" = EXCLUDED."rowProjectGUID", "rowOrganizationGUID" = EXCLUDED."rowOrganizationGUID", "rowOwnerUserGUID" = EXCLUDED."rowOwnerUserGUID",
               "projectName" = EXCLUDED."projectName", "taskName" = EXCLUDED."taskName", "resourceRoleName" = EXCLUDED."resourceRoleName",
               "qtyPlanned" = EXCLUDED."qtyPlanned", "qtyContracted" = EXCLUDED."qtyContracted", "sumForBudget" = EXCLUDED."sumForBudget", "qtyUsed" = EXCLUDED."qtyUsed", "qtyVendorInvoiced" = EXCLUDED."qtyVendorInvoiced", "sumVendorInvoiced" = EXCLUDED."sumVendorInvoiced", "qtyOrdered" = EXCLUDED."qtyOrdered", "qtyReceived" = EXCLUDED."qtyReceived", "qtyCustomerInvoiced" = EXCLUDED."qtyCustomerInvoiced", "sumCustomerInvoiced" = EXCLUDED."sumCustomerInvoiced", "vatBudget" = EXCLUDED."vatBudget", "vatInCostBudget" = EXCLUDED."vatInCostBudget", "vatVendorInvoiced" = EXCLUDED."vatVendorInvoiced", "vatInCostVendorInvoiced" = EXCLUDED."vatInCostVendorInvoiced", "vatCustomerInvoiced" = EXCLUDED."vatCustomerInvoiced", "lineCount" = EXCLUDED."lineCount", "hasStalePlan" = EXCLUDED."hasStalePlan", "updated_at" = NOW()
         WHERE (v."rowProjectGUID", v."rowOrganizationGUID", v."rowOwnerUserGUID", v."projectName", v."taskName", v."resourceRoleName", v."qtyPlanned", v."qtyContracted", v."sumForBudget", v."qtyUsed", v."qtyVendorInvoiced", v."sumVendorInvoiced", v."qtyOrdered", v."qtyReceived", v."qtyCustomerInvoiced", v."sumCustomerInvoiced", v."vatBudget", v."vatInCostBudget", v."vatVendorInvoiced", v."vatInCostVendorInvoiced", v."vatCustomerInvoiced", v."lineCount", v."hasStalePlan")
               IS DISTINCT FROM (EXCLUDED."rowProjectGUID", EXCLUDED."rowOrganizationGUID", EXCLUDED."rowOwnerUserGUID", EXCLUDED."projectName", EXCLUDED."taskName", EXCLUDED."resourceRoleName",
                                 EXCLUDED."qtyPlanned", EXCLUDED."qtyContracted", EXCLUDED."sumForBudget", EXCLUDED."qtyUsed", EXCLUDED."qtyVendorInvoiced", EXCLUDED."sumVendorInvoiced", EXCLUDED."qtyOrdered", EXCLUDED."qtyReceived", EXCLUDED."qtyCustomerInvoiced", EXCLUDED."sumCustomerInvoiced", EXCLUDED."vatBudget", EXCLUDED."vatInCostBudget", EXCLUDED."vatVendorInvoiced", EXCLUDED."vatInCostVendorInvoiced", EXCLUDED."vatCustomerInvoiced", EXCLUDED."lineCount", EXCLUDED."hasStalePlan")
         RETURNING 1),
       del AS (
         DELETE FROM public.monitor01_view v
          WHERE v."rowOwnerGUID" = ANY (p_tasks)
            AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f."rowOwnerGUID" = v."rowOwnerGUID" AND f."genusGUID" = v."genusGUID" AND f."resourceRoleGUID" = v."resourceRoleGUID"
                                                    AND f."measureUnit" = v."measureUnit" AND f."periodMonth" = v."periodMonth")
         RETURNING 1)
  SELECT (SELECT count(*) FROM up), (SELECT count(*) FROM del) INTO v_u, v_d;

  -- step 3 (PART 27): the cost total of the tasks and of the stages above them. A failure here must never stop Monitor01: it is a warning, the toolbar command (update_project_cost_total) heals it.
  BEGIN
    PERFORM public.project_cost_apply(p_tasks);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'project_cost_apply failed: %', SQLERRM;
  END;

  -- step 4 (PART 29): the origin tasks that aggregate the numbers of these tasks are queued (nothing happens when there is no subproject link)
  BEGIN
    PERFORM public.subproject_queue_origins(p_tasks);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'subproject_queue_origins failed: %', SQLERRM;
  END;

  -- step 5 (PART 33): the ROI money of these tasks (task x month); the project months follow by the triggers of that table. A failure here must never stop Monitor01: it is a warning, roi_rebuild heals it.
  BEGIN
    PERFORM public.roi_apply(p_tasks);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'roi_apply failed: %', SQLERRM;
  END;

  p_upserted := v_u + v_fu;
  p_deleted  := v_d + v_fd;
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_apply(uuid[]) FROM PUBLIC, anon, authenticated;


-- ONE batch: claim up to p_batch tasks (oldest first, SKIP LOCKED, so two workers never take the same task), apply them, log. A failing batch is retried task by task, so ONE bad task
-- is parked (attempts 5) and never blocks the others. Returns the number of tasks taken (0 = the queue is empty). No COMMIT inside: tests call it in a transaction; the procedure below commits.
CREATE OR REPLACE FUNCTION public.monitor01_process_batch(p_batch integer DEFAULT 500) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_tasks uuid[]; v_lag interval; v_att jsonb; v_t0 timestamptz := clock_timestamp();
  v_up integer := 0; v_del integer := 0; v_u integer; v_d integer; v_one uuid; v_parked integer;
BEGIN
  PERFORM public.project_cost_process_dirty();      -- (PART 27) the projects whose stages were moved / deleted are rebuilt (a tiny queue, usually empty)
  WITH c AS (SELECT d."rowOwnerGUID", d."queuedAt" FROM public.monitor01_dirty d WHERE d."attempts" < 5 ORDER BY d."queuedAt" LIMIT p_batch FOR UPDATE SKIP LOCKED),
       x AS (DELETE FROM public.monitor01_dirty d USING c WHERE d."rowOwnerGUID" = c."rowOwnerGUID" RETURNING d."rowOwnerGUID", c."queuedAt", d."attempts")
  SELECT array_agg(x."rowOwnerGUID"), clock_timestamp() - min(x."queuedAt"), jsonb_object_agg(x."rowOwnerGUID"::text, x."attempts") INTO v_tasks, v_lag, v_att FROM x;
  IF v_tasks IS NULL THEN
    RETURN 0;
  END IF;

  BEGIN
    SELECT a.p_upserted, a.p_deleted INTO v_up, v_del FROM public.monitor01_apply(v_tasks) a;
  EXCEPTION WHEN OTHERS THEN
    v_up := 0; v_del := 0;
    FOREACH v_one IN ARRAY v_tasks LOOP
      BEGIN
        SELECT a.p_upserted, a.p_deleted INTO v_u, v_d FROM public.monitor01_apply(ARRAY[v_one]) a;
        v_up := v_up + v_u; v_del := v_del + v_d;
      EXCEPTION WHEN OTHERS THEN
        INSERT INTO public.monitor01_dirty AS q ("rowOwnerGUID", "reason", "attempts", "lastError") VALUES (v_one, 'retry', COALESCE((v_att->>v_one::text)::integer, 0) + 1, left(SQLERRM, 500))
        ON CONFLICT ("rowOwnerGUID") DO UPDATE SET "attempts" = GREATEST(q."attempts", EXCLUDED."attempts"), "lastError" = left(SQLERRM, 500);
      END;
    END LOOP;
  END;

  SELECT count(*) INTO v_parked FROM public.monitor01_dirty WHERE "attempts" >= 5;
  INSERT INTO public.monitor01_refresh_log ("tasksTaken", "rowsUpserted", "rowsDeleted", "durationMs", "maxLagMs", "parkedTasks")
  VALUES (cardinality(v_tasks), v_up, v_del, (extract(epoch FROM clock_timestamp() - v_t0) * 1000)::integer, (extract(epoch FROM v_lag) * 1000)::integer, v_parked);
  RETURN cardinality(v_tasks);
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_process_batch(integer) FROM PUBLIC, anon, authenticated;


-- what pg_cron calls every 2 seconds: batches while the queue is not empty and the time budget lasts, COMMIT after each batch (a procedure without SET / SECURITY DEFINER may commit)
CREATE OR REPLACE PROCEDURE public.monitor01_process_dirty(p_batch integer DEFAULT 500, p_budget_ms integer DEFAULT 1500)
LANGUAGE plpgsql AS $$
DECLARE
  v_t0 timestamptz := clock_timestamp();
  v_n integer;
BEGIN
  LOOP
    v_n := public.monitor01_process_batch(p_batch);
    COMMIT;
    EXIT WHEN v_n = 0 OR extract(epoch FROM clock_timestamp() - v_t0) * 1000 > p_budget_ms;
  END LOOP;
END;
$$;

REVOKE ALL ON PROCEDURE public.monitor01_process_dirty(integer, integer) FROM PUBLIC, anon, authenticated;


-- ---- queue helpers + triggers: they ONLY write the task keys ------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.monitor01_queue_tasks(p_tasks uuid[], p_reason text DEFAULT NULL) RETURNS integer
LANGUAGE sql SECURITY DEFINER SET search_path = public, extensions AS $$
  WITH q AS (
    INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
    SELECT DISTINCT t, p_reason FROM unnest(p_tasks) AS t WHERE t IS NOT NULL
    ON CONFLICT ("rowOwnerGUID") DO NOTHING RETURNING 1)
  SELECT count(*)::integer FROM q
$$;

REVOKE ALL ON FUNCTION public.monitor01_queue_tasks(uuid[], text) FROM PUBLIC, anon, authenticated;


-- statement level, with a transition table: ONE insert per statement, whatever the number of rows. The same function for the movements and for the task lines (the column is rowOwnerGUID).
CREATE OR REPLACE FUNCTION public.monitor01_trg_queue_new() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") SELECT DISTINCT n."rowOwnerGUID", TG_ARGV[0] FROM new_rows n ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.monitor01_trg_queue_old() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") SELECT DISTINCT o."rowOwnerGUID", TG_ARGV[0] FROM old_rows o ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;


DROP TRIGGER IF EXISTS trg_monitor01_movements_ins ON public.task_line_plan_movements;

CREATE TRIGGER trg_monitor01_movements_ins AFTER INSERT ON public.task_line_plan_movements REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_new('plan');

DROP TRIGGER IF EXISTS trg_monitor01_movements_upd ON public.task_line_plan_movements;

CREATE TRIGGER trg_monitor01_movements_upd AFTER UPDATE ON public.task_line_plan_movements REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_new('plan');

DROP TRIGGER IF EXISTS trg_monitor01_movements_del ON public.task_line_plan_movements;

CREATE TRIGGER trg_monitor01_movements_del AFTER DELETE ON public.task_line_plan_movements REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_old('plan');


DROP TRIGGER IF EXISTS trg_monitor01_lines_ins ON public.task_line_table;

CREATE TRIGGER trg_monitor01_lines_ins AFTER INSERT ON public.task_line_table REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_new('line');

DROP TRIGGER IF EXISTS trg_monitor01_lines_upd ON public.task_line_table;

CREATE TRIGGER trg_monitor01_lines_upd AFTER UPDATE ON public.task_line_table REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_new('line');

DROP TRIGGER IF EXISTS trg_monitor01_lines_del ON public.task_line_table;

CREATE TRIGGER trg_monitor01_lines_del AFTER DELETE ON public.task_line_table REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.monitor01_trg_queue_old('line');


-- a fact document is counted ONLY while it is posted: Post / Unpost / delete of a posted document queue its task
CREATE OR REPLACE FUNCTION public.monitor01_trg_fact_header() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF COALESCE(OLD."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
      INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") VALUES (OLD."rowOwnerGUID", 'fact') ON CONFLICT ("rowOwnerGUID") DO NOTHING;
    END IF;
    RETURN OLD;
  END IF;
  IF COALESCE(OLD."rowJSON"->'documentHeader'->>'documentStatus', 'draft') IS DISTINCT FROM COALESCE(NEW."rowJSON"->'documentHeader'->>'documentStatus', 'draft') THEN
    INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") VALUES (NEW."rowOwnerGUID", 'fact') ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_monitor01_fact_header ON public.task_fact_header;

CREATE TRIGGER trg_monitor01_fact_header AFTER UPDATE OR DELETE ON public.task_fact_header FOR EACH ROW EXECUTE FUNCTION public.monitor01_trg_fact_header();


-- renames: the names are copied into the rows (filters and the screen need no catalog)
CREATE OR REPLACE FUNCTION public.monitor01_trg_task_rename() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") VALUES (NEW."rowGUID", 'rename') ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_monitor01_task_rename ON public.project_task_table;

CREATE TRIGGER trg_monitor01_task_rename AFTER UPDATE OF "rowJSON" ON public.project_task_table
  FOR EACH ROW WHEN (OLD."rowJSON"->>'taskDescription' IS DISTINCT FROM NEW."rowJSON"->>'taskDescription') EXECUTE FUNCTION public.monitor01_trg_task_rename();


CREATE OR REPLACE FUNCTION public.monitor01_trg_project_rename() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
  SELECT DISTINCT v."rowOwnerGUID", 'rename' FROM public.monitor01_view v WHERE v."rowProjectGUID" = NEW."rowGUID"
  ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_monitor01_project_rename ON public.project_table;

CREATE TRIGGER trg_monitor01_project_rename AFTER UPDATE OF "rowJSON", "rowOwnerGUID" ON public.project_table
  FOR EACH ROW WHEN (OLD."rowJSON"->>'name' IS DISTINCT FROM NEW."rowJSON"->>'name' OR OLD."rowJSON"->>'title' IS DISTINCT FROM NEW."rowJSON"->>'title' OR OLD."rowOwnerGUID" IS DISTINCT FROM NEW."rowOwnerGUID")
  EXECUTE FUNCTION public.monitor01_trg_project_rename();


CREATE OR REPLACE FUNCTION public.monitor01_trg_role_rename() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
  SELECT DISTINCT v."rowOwnerGUID", 'rename' FROM public.monitor01_view v WHERE v."resourceRoleGUID" = NEW."rowGUID"
  ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_monitor01_role_rename ON public."resourceRoleTable";

CREATE TRIGGER trg_monitor01_role_rename AFTER UPDATE OF "rowJSON" ON public."resourceRoleTable"
  FOR EACH ROW WHEN (OLD."rowJSON"->>'title' IS DISTINCT FROM NEW."rowJSON"->>'title') EXECUTE FUNCTION public.monitor01_trg_role_rename();


-- the register changed by a document (used / invoiced): the task is queued. The PLAN movements are rewritten by the worker itself - they must not queue (it would never end).
CREATE OR REPLACE FUNCTION public.project_status_trg_queue_new() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") SELECT DISTINCT n."rowOwnerGUID", 'register' FROM new_rows n WHERE n."rowMovementKind" <> 'plan' ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.project_status_trg_queue_old() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason") SELECT DISTINCT o."rowOwnerGUID", 'register' FROM old_rows o WHERE o."rowMovementKind" <> 'plan' ON CONFLICT ("rowOwnerGUID") DO NOTHING;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_project_status_movements_ins ON public.project_status_movements;

CREATE TRIGGER trg_project_status_movements_ins AFTER INSERT ON public.project_status_movements REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.project_status_trg_queue_new();

DROP TRIGGER IF EXISTS trg_project_status_movements_del ON public.project_status_movements;

CREATE TRIGGER trg_project_status_movements_del AFTER DELETE ON public.project_status_movements REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.project_status_trg_queue_old();


-- upgrade: the posted fact documents that are not in the register yet are registered once (idempotent: a registered document is skipped)
SELECT public.project_status_register_fact(h."rowGUID")
  FROM public.task_fact_header h
 WHERE COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted'
   AND NOT EXISTS (SELECT 1 FROM public.project_status_movements s WHERE s."rowRegistratorGUID" = h."rowGUID");


-- upgrade: the tasks whose plan is not in the register yet are queued (the worker registers the plan of its batch); a task that has nothing to register is only looked at again
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT m."rowOwnerGUID", 'install' FROM public.task_line_plan_movements m
 WHERE NOT EXISTS (SELECT 1 FROM public.project_status_movements s WHERE s."rowMovementKind" = 'plan' AND s."rowOwnerGUID" = m."rowOwnerGUID")
ON CONFLICT ("rowOwnerGUID") DO NOTHING;


-- ---- rebuild / verify (the safety net: anything that bypassed the triggers - TRUNCATE, an import with triggers off) -----------------------------------------
-- queue every task of one project (or of everything) that has plan movements or posted facts or rows in the view
CREATE OR REPLACE FUNCTION public.monitor01_rebuild(p_project uuid DEFAULT NULL) RETURNS integer
LANGUAGE sql SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT public.monitor01_queue_tasks(ARRAY(
    SELECT m."rowOwnerGUID" FROM public.task_line_plan_movements m WHERE p_project IS NULL OR m."rowProjectGUID" = p_project
    UNION SELECT f."rowOwnerGUID" FROM public.task_fact_usage_timeline f WHERE p_project IS NULL OR f."rowProjectGUID" = p_project
    UNION SELECT v."rowOwnerGUID" FROM public.monitor01_view v WHERE p_project IS NULL OR v."rowProjectGUID" = p_project), 'rebuild')
$$;

REVOKE ALL ON FUNCTION public.monitor01_rebuild(uuid) FROM PUBLIC, anon, authenticated;


-- compare a random sample of tasks with the fresh numbers and queue the ones that differ; returns how many were queued
CREATE OR REPLACE FUNCTION public.monitor01_verify(p_sample integer DEFAULT 200) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_sample uuid[];
  v_bad uuid[];
BEGIN
  SELECT array_agg(s.t) INTO v_sample FROM (
    SELECT t FROM (SELECT DISTINCT m."rowOwnerGUID" AS t FROM public.task_line_plan_movements m
                   UNION SELECT v."rowOwnerGUID" FROM public.monitor01_view v) u ORDER BY random() LIMIT p_sample) s;
  IF v_sample IS NULL THEN RETURN 0; END IF;
  SELECT array_agg(DISTINCT d.task) INTO v_bad FROM (
    (SELECT f."rowOwnerGUID" AS task, f."genusGUID", f."resourceRoleGUID", f."measureUnit", f."periodMonth", f."rowProjectGUID", f."rowOrganizationGUID", f."rowOwnerUserGUID", f."projectName", f."taskName", f."resourceRoleName",
             f."qtyPlanned", f."qtyContracted", f."sumForBudget", f."qtyUsed", f."qtyVendorInvoiced", f."sumVendorInvoiced", f."qtyOrdered", f."qtyReceived", f."qtyCustomerInvoiced", f."sumCustomerInvoiced", f."vatBudget", f."vatInCostBudget", f."vatVendorInvoiced", f."vatInCostVendorInvoiced", f."vatCustomerInvoiced", f."lineCount", f."hasStalePlan" FROM public.monitor01_fresh_rows(v_sample) f
      EXCEPT
      SELECT v."rowOwnerGUID", v."genusGUID", v."resourceRoleGUID", v."measureUnit", v."periodMonth", v."rowProjectGUID", v."rowOrganizationGUID", v."rowOwnerUserGUID", v."projectName", v."taskName", v."resourceRoleName",
             v."qtyPlanned", v."qtyContracted", v."sumForBudget", v."qtyUsed", v."qtyVendorInvoiced", v."sumVendorInvoiced", v."qtyOrdered", v."qtyReceived", v."qtyCustomerInvoiced", v."sumCustomerInvoiced", v."vatBudget", v."vatInCostBudget", v."vatVendorInvoiced", v."vatInCostVendorInvoiced", v."vatCustomerInvoiced", v."lineCount", v."hasStalePlan" FROM public.monitor01_view v WHERE v."rowOwnerGUID" = ANY (v_sample))
    UNION ALL
    (SELECT v."rowOwnerGUID", v."genusGUID", v."resourceRoleGUID", v."measureUnit", v."periodMonth", v."rowProjectGUID", v."rowOrganizationGUID", v."rowOwnerUserGUID", v."projectName", v."taskName", v."resourceRoleName",
             v."qtyPlanned", v."qtyContracted", v."sumForBudget", v."qtyUsed", v."qtyVendorInvoiced", v."sumVendorInvoiced", v."qtyOrdered", v."qtyReceived", v."qtyCustomerInvoiced", v."sumCustomerInvoiced", v."vatBudget", v."vatInCostBudget", v."vatVendorInvoiced", v."vatInCostVendorInvoiced", v."vatCustomerInvoiced", v."lineCount", v."hasStalePlan" FROM public.monitor01_view v WHERE v."rowOwnerGUID" = ANY (v_sample)
      EXCEPT
      SELECT f."rowOwnerGUID", f."genusGUID", f."resourceRoleGUID", f."measureUnit", f."periodMonth", f."rowProjectGUID", f."rowOrganizationGUID", f."rowOwnerUserGUID", f."projectName", f."taskName", f."resourceRoleName",
             f."qtyPlanned", f."qtyContracted", f."sumForBudget", f."qtyUsed", f."qtyVendorInvoiced", f."sumVendorInvoiced", f."qtyOrdered", f."qtyReceived", f."qtyCustomerInvoiced", f."sumCustomerInvoiced", f."vatBudget", f."vatInCostBudget", f."vatVendorInvoiced", f."vatInCostVendorInvoiced", f."vatCustomerInvoiced", f."lineCount", f."hasStalePlan" FROM public.monitor01_fresh_rows(v_sample) f)) d;
  RETURN public.monitor01_queue_tasks(v_bad, 'verify');
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_verify(integer) FROM PUBLIC, anon, authenticated;


-- housekeeping (daily): the log of the worker keeps 3 days, and a sample is verified
CREATE OR REPLACE FUNCTION public.monitor01_housekeeping() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  DELETE FROM public.monitor01_refresh_log WHERE "ranAt" < NOW() - INTERVAL '3 days';
  RETURN public.monitor01_verify(500);
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_housekeeping() FROM PUBLIC, anon, authenticated;


-- ---- the source transactions of any sum (SumExplorerListReusable.tsx) --------------------------------------------------------------------------------------
-- SECURITY INVOKER: the policies of the source tables apply (the owner of the project only). p_filter keys (all optional): projectGUID · taskGUID · genusGUID · roleGUID ('' = no role) · unit ·
-- taskGUIDs · roleGUIDs (arrays, for a subtotal under filters) · month ('YYYY-MM-01') · fromMonth · toMonth. Measures: planned · contracted (the movements) · fact (the lines of the POSTED fact documents) · used · vendorInvoiced (posted vendor invoices) · ordered (posted purchase orders) · received (posted product receipts).
CREATE OR REPLACE FUNCTION public.monitor01_sum_sources(p_measure text, p_filter jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
DECLARE
  v_rows jsonb; v_count bigint; v_sum numeric;
  f jsonb := COALESCE(p_filter, '{}'::jsonb);
BEGIN
  IF p_measure IN ('planned', 'contracted') THEN
    WITH src AS (
      SELECT m."rowGUID"::text AS "rowGUID", 'taskLinePlanMovements'::text AS "sourceName",
             COALESCE(m."periodDay", ((m."rowPeriodDatetime" + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date) AS "day",
             m."rowOwnerGUID"::text AS "taskGUID", m."rowProjectGUID"::text AS "projectGUID", m."rowParentGUID"::text AS "lineGUID",
             l."rowParentGUID" AS "genusGUID", COALESCE(l."rowJSON"->>'resourceRoleItem', '') AS "roleGUID", COALESCE(l."rowJSON"->>'measureUnitTaskLine', '') AS "unit",
             COALESCE(m."qtyTaskLine", 0) AS "qty",
             NULLIF(CASE WHEN l."rowParentGUID" = 'timeGenus' THEN l."rowJSON"->>'taskResourceContract' ELSE l."rowJSON"->>'taskLinePartnerContract' END, '') AS "contractGUID",
             NOT COALESCE((l."rowJSON"->>'taskIsPosted')::boolean, false) AS "stale"
        FROM public.task_line_plan_movements m JOIN public.task_line_table l ON l."rowGUID" = m."rowParentGUID"
       WHERE m."planMovementStatus" AND l."rowParentGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus')
         AND (NOT f ? 'projectGUID' OR m."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR m."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', m."rowOwnerGUID", l."rowParentGUID"))
         AND (NOT f ? 'taskGUIDs'   OR m."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR l."rowParentGUID"  = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR COALESCE(l."rowJSON"->>'resourceRoleItem', '') = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR COALESCE(l."rowJSON"->>'resourceRoleItem', '') IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR COALESCE(l."rowJSON"->>'measureUnitTaskLine', '') = f->>'unit')
    ), flt AS (
      SELECT s.* FROM src s
       WHERE (NOT f ? 'month'     OR date_trunc('month', s."day")::date = (f->>'month')::date)
         AND (NOT f ? 'fromMonth' OR date_trunc('month', s."day")::date >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'   OR date_trunc('month', s."day")::date <= (f->>'toMonth')::date)
         AND (p_measure = 'planned' OR s."contractGUID" IS NOT NULL)
    ), pg AS (SELECT * FROM flt ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM flt), (SELECT COALESCE(sum("qty"), 0) FROM flt), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSIF p_measure IN ('fact', 'used') THEN
    WITH src AS (
     SELECT * FROM (
      SELECT x."rowGUID"::text AS "rowGUID", 'taskFactUsageTimeline'::text AS "sourceName", x."periodDay" AS "day", x."rowOwnerGUID"::text AS "taskGUID", x."rowProjectGUID"::text AS "projectGUID",
             x."taskLineGUID"::text AS "lineGUID", x."rowHeaderGUID"::text AS "documentGUID", h."rowJSON"->'documentHeader'->>'documentNumber' AS "documentNumber",
             x."genusGUID", COALESCE(x."rowJSON"->>'resourceRoleItem', '') AS "roleGUID", COALESCE(x."rowJSON"->>'measureUnitTaskLine', '') AS "unit", x."qtyForContract" AS "qty"
        FROM public.task_fact_usage_timeline x JOIN public.task_fact_header h ON h."rowGUID" = x."rowHeaderGUID"
       WHERE COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted'
         AND (NOT f ? 'projectGUID' OR x."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR x."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', x."rowOwnerGUID", x."genusGUID"))
         AND (NOT f ? 'taskGUIDs'   OR x."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR x."genusGUID"      = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR COALESCE(x."rowJSON"->>'resourceRoleItem', '') = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR COALESCE(x."rowJSON"->>'resourceRoleItem', '') IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR COALESCE(x."rowJSON"->>'measureUnitTaskLine', '') = f->>'unit')
         AND (NOT f ? 'month'       OR date_trunc('month', x."periodDay")::date = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR date_trunc('month', x."periodDay")::date >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR date_trunc('month', x."periodDay")::date <= (f->>'toMonth')::date)
      UNION ALL
      -- (time sheet, PART 36) the entered hours of the POSTED time sheets (one row = one cell of a line)
      SELECT x."rowGUID"::text, 'projectTimesheetLinesDataEntered'::text, x."timesheetDay", l."timesheetLineTask"::text, l."timesheetLineProject"::text,
             NULL::text, x."rowHeaderGUID"::text, h."rowJSON"->'documentHeader'->>'documentNumber', 'timeGenus'::text, COALESCE(l."timesheetLineRole", ''), 'unit_hour'::text, x."timesheetHours"
        FROM public.project_timesheet_lines_data_entered x JOIN public.project_timesheet_lines l ON l."rowGUID" = x."rowLineGUID" JOIN public.project_timesheet_header h ON h."rowGUID" = x."rowHeaderGUID"
       WHERE COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted'
         AND (NOT f ? 'projectGUID' OR l."timesheetLineProject" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR l."timesheetLineTask"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', l."timesheetLineTask", 'timeGenus'))
         AND (NOT f ? 'taskGUIDs'   OR l."timesheetLineTask"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR f->>'genusGUID' = 'timeGenus')
         AND (NOT f ? 'roleGUID'    OR COALESCE(l."timesheetLineRole", '') = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR COALESCE(l."timesheetLineRole", '') IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR f->>'unit' = 'unit_hour')
         AND (NOT f ? 'month'       OR date_trunc('month', x."timesheetDay")::date = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR date_trunc('month', x."timesheetDay")::date >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR date_trunc('month', x."timesheetDay")::date <= (f->>'toMonth')::date)
     ) u
    ), pg AS (SELECT * FROM src ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM src), (SELECT COALESCE(sum("qty"), 0) FROM src), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSIF p_measure = 'vendorInvoiced' THEN
    WITH src AS (
      SELECT s."rowGUID"::text AS "rowGUID", 'projectStatusMovements'::text AS "sourceName", s."rowTurnoverDay" AS "day", s."rowOwnerGUID"::text AS "taskGUID", s."rowProjectGUID"::text AS "projectGUID",
             s."rowProjectTaskLineGUID"::text AS "lineGUID", s."rowRegistratorGUID"::text AS "documentGUID", h."rowJSON"->>'vendorInvoiceNumber' AS "documentNumber",
             s."genusGUID", s."resourceRoleGUID" AS "roleGUID", s."measureUnit" AS "unit", s."qtyProjectStatus" AS "qty"
        FROM public.project_status_movements s
        JOIN public.vendor_invoice_header h ON h."rowGUID" = s."rowRegistratorGUID"
       WHERE s."rowMovementKind" = 'invoiced'
         AND (NOT f ? 'projectGUID' OR s."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR s."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', s."rowOwnerGUID", s."genusGUID"))
         AND (NOT f ? 'taskGUIDs'   OR s."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR s."genusGUID"      = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR s."resourceRoleGUID" = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR s."resourceRoleGUID" IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR s."measureUnit" = f->>'unit')
         AND (NOT f ? 'month'       OR s."rowTurnoverMonth" = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR s."rowTurnoverMonth" >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR s."rowTurnoverMonth" <= (f->>'toMonth')::date)
    ), pg AS (SELECT * FROM src ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM src), (SELECT COALESCE(sum("qty"), 0) FROM src), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSIF p_measure = 'customerInvoiced' THEN
    WITH src AS (
      SELECT s."rowGUID"::text AS "rowGUID", 'projectStatusMovements'::text AS "sourceName", s."rowTurnoverDay" AS "day", s."rowOwnerGUID"::text AS "taskGUID", s."rowProjectGUID"::text AS "projectGUID",
             s."rowProjectTaskLineGUID"::text AS "lineGUID", s."rowRegistratorGUID"::text AS "documentGUID", h."rowJSON"->>'customerInvoiceNumber' AS "documentNumber",
             s."genusGUID", s."resourceRoleGUID" AS "roleGUID", s."measureUnit" AS "unit", s."qtyProjectStatus" AS "qty"
        FROM public.project_status_movements s
        JOIN public.customer_invoice_header h ON h."rowGUID" = s."rowRegistratorGUID"
       WHERE s."rowMovementKind" = 'sold'
         AND (NOT f ? 'projectGUID' OR s."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR s."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', s."rowOwnerGUID", s."genusGUID"))
         AND (NOT f ? 'taskGUIDs'   OR s."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR s."genusGUID"      = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR s."resourceRoleGUID" = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR s."resourceRoleGUID" IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR s."measureUnit" = f->>'unit')
         AND (NOT f ? 'month'       OR s."rowTurnoverMonth" = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR s."rowTurnoverMonth" >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR s."rowTurnoverMonth" <= (f->>'toMonth')::date)
    ), pg AS (SELECT * FROM src ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM src), (SELECT COALESCE(sum("qty"), 0) FROM src), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSIF p_measure = 'ordered' THEN
    WITH src AS (
      SELECT s."rowGUID"::text AS "rowGUID", 'projectStatusMovements'::text AS "sourceName", s."rowTurnoverDay" AS "day", s."rowOwnerGUID"::text AS "taskGUID", s."rowProjectGUID"::text AS "projectGUID",
             s."rowProjectTaskLineGUID"::text AS "lineGUID", s."rowRegistratorGUID"::text AS "documentGUID", h."rowJSON"->>'purchaseOrderNumber' AS "documentNumber",
             s."genusGUID", s."resourceRoleGUID" AS "roleGUID", s."measureUnit" AS "unit", s."qtyProjectStatus" AS "qty"
        FROM public.project_status_movements s
        JOIN public.purchase_order_header h ON h."rowGUID" = s."rowRegistratorGUID"
       WHERE s."rowMovementKind" = 'ordered'
         AND (NOT f ? 'projectGUID' OR s."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR s."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', s."rowOwnerGUID", s."genusGUID"))
         AND (NOT f ? 'taskGUIDs'   OR s."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR s."genusGUID"      = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR s."resourceRoleGUID" = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR s."resourceRoleGUID" IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR s."measureUnit" = f->>'unit')
         AND (NOT f ? 'month'       OR s."rowTurnoverMonth" = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR s."rowTurnoverMonth" >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR s."rowTurnoverMonth" <= (f->>'toMonth')::date)
    ), pg AS (SELECT * FROM src ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM src), (SELECT COALESCE(sum("qty"), 0) FROM src), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSIF p_measure = 'received' THEN
    WITH src AS (
      SELECT s."rowGUID"::text AS "rowGUID", 'projectStatusMovements'::text AS "sourceName", s."rowTurnoverDay" AS "day", s."rowOwnerGUID"::text AS "taskGUID", s."rowProjectGUID"::text AS "projectGUID",
             s."rowProjectTaskLineGUID"::text AS "lineGUID", s."rowRegistratorGUID"::text AS "documentGUID", h."rowJSON"->>'productReceiptNumber' AS "documentNumber",
             s."genusGUID", s."resourceRoleGUID" AS "roleGUID", s."measureUnit" AS "unit", s."qtyProjectStatus" AS "qty"
        FROM public.project_status_movements s
        JOIN public.product_receipt_header h ON h."rowGUID" = s."rowRegistratorGUID"
       WHERE s."rowMovementKind" = 'received'
         AND (NOT f ? 'projectGUID' OR s."rowProjectGUID" = (f->>'projectGUID')::uuid)
         AND (NOT f ? 'taskGUID'    OR s."rowOwnerGUID"   = (f->>'taskGUID')::uuid OR public.subproject_drill_match(f->>'taskGUID', s."rowOwnerGUID", s."genusGUID"))
         AND (NOT f ? 'taskGUIDs'   OR s."rowOwnerGUID"::text IN (SELECT jsonb_array_elements_text(f->'taskGUIDs')))
         AND (NOT f ? 'genusGUID'   OR s."genusGUID"      = f->>'genusGUID')
         AND (NOT f ? 'roleGUID'    OR s."resourceRoleGUID" = f->>'roleGUID')
         AND (NOT f ? 'roleGUIDs'   OR s."resourceRoleGUID" IN (SELECT jsonb_array_elements_text(f->'roleGUIDs')))
         AND (NOT f ? 'unit'        OR s."measureUnit" = f->>'unit')
         AND (NOT f ? 'month'       OR s."rowTurnoverMonth" = (f->>'month')::date)
         AND (NOT f ? 'fromMonth'   OR s."rowTurnoverMonth" >= (f->>'fromMonth')::date)
         AND (NOT f ? 'toMonth'     OR s."rowTurnoverMonth" <= (f->>'toMonth')::date)
    ), pg AS (SELECT * FROM src ORDER BY "day" DESC, "rowGUID" LIMIT p_limit OFFSET p_offset),
       pgn AS (SELECT pg.*, t."rowJSON"->>'taskDescription' AS "taskName", r."rowJSON"->>'title' AS "roleName"
                 FROM pg LEFT JOIN public.project_task_table t ON t."rowGUID" = pg."taskGUID"::uuid
                         LEFT JOIN public."resourceRoleTable" r ON r."rowGUID" = NULLIF(pg."roleGUID", ''))
    SELECT (SELECT count(*) FROM src), (SELECT COALESCE(sum("qty"), 0) FROM src), COALESCE((SELECT jsonb_agg(to_jsonb(pgn) ORDER BY pgn."day" DESC, pgn."rowGUID") FROM pgn), '[]'::jsonb)
      INTO v_count, v_sum, v_rows;
  ELSE
    RAISE EXCEPTION 'unknown measure %', p_measure USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('measure', p_measure, 'totalCount', v_count, 'sum', v_sum, 'rows', v_rows);
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_sum_sources(text, jsonb, integer, integer) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.monitor01_sum_sources(text, jsonb, integer, integer) TO authenticated;


-- ---- refresh NOW: the "Refresh" button of the report and its first look. The worker (pg_cron) is the normal way; this is for the moment it is not running (the pg_cron extension is not enabled, the
-- "N seconds" schedule was refused) or has not come yet: it recomputes the tasks of the USER'S OWN projects (plan movements, posted facts, rows of the view) at once, in the same way as the worker (monitor01_apply),
-- and removes them from the queue. An error is NOT swallowed: the screen shows its message. Returns { tasks, upserted, deleted }.
CREATE OR REPLACE FUNCTION public.monitor01_refresh_now(p_project uuid DEFAULT NULL, p_max integer DEFAULT 2000) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_tasks uuid[]; v_up integer := 0; v_del integer := 0;
BEGIN
  SELECT array_agg(s.t) INTO v_tasks FROM (
    SELECT DISTINCT x.t FROM (
      SELECT m."rowOwnerGUID" AS t, m."rowProjectGUID" AS pr FROM public.task_line_plan_movements m
      UNION SELECT f."rowOwnerGUID", f."rowProjectGUID" FROM public.task_fact_usage_timeline f
      UNION SELECT v."rowOwnerGUID", v."rowProjectGUID" FROM public.monitor01_view v
      UNION SELECT k."rowOwnerGUID", k."rowProjectGUID" FROM public.project_subproject_link k) x
     WHERE public.pm_owns_project(x.pr) AND (p_project IS NULL OR x.pr = p_project)
     LIMIT GREATEST(p_max, 1)) s;
  IF v_tasks IS NULL THEN
    RETURN jsonb_build_object('tasks', 0, 'upserted', 0, 'deleted', 0);
  END IF;
  SELECT a.p_upserted, a.p_deleted INTO v_up, v_del FROM public.monitor01_apply(v_tasks) a;
  DELETE FROM public.monitor01_dirty q WHERE q."rowOwnerGUID" = ANY (v_tasks);
  RETURN jsonb_build_object('tasks', cardinality(v_tasks), 'upserted', v_up, 'deleted', v_del);
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_refresh_now(uuid, integer) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.monitor01_refresh_now(uuid, integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.monitor01_stamp(p_project uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_count bigint; v_max timestamptz; v_queued bigint; v_age numeric;
BEGIN
  SELECT count(*), max(v."updated_at") INTO v_count, v_max FROM public.monitor01_view v
   WHERE v."rowOwnerUserGUID" = public.app_user_guid() AND (p_project IS NULL OR v."rowProjectGUID" = p_project);
  SELECT count(*), COALESCE(extract(epoch FROM clock_timestamp() - min(d."queuedAt")), 0) INTO v_queued, v_age
    FROM public.monitor01_dirty d JOIN public.project_task_table t ON t."rowGUID" = d."rowOwnerGUID"
   WHERE d."attempts" < 5 AND public.pm_owns_project(t."projectGUID") AND (p_project IS NULL OR t."projectGUID" = p_project);
  RETURN jsonb_build_object('count', v_count, 'maxUpdatedAt', v_max, 'queued', v_queued, 'queuedAgeSeconds', round(v_age, 1));
END;
$$;

REVOKE ALL ON FUNCTION public.monitor01_stamp(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.monitor01_stamp(uuid) TO authenticated;


-- ---- first fill: the install only QUEUES the tasks (no heavy statement inside the install); the worker fills the view in the next ticks. Only when the view is empty ----
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT m."rowOwnerGUID", 'install' FROM public.task_line_plan_movements m
 WHERE NOT EXISTS (SELECT 1 FROM public.monitor01_view LIMIT 1)
ON CONFLICT ("rowOwnerGUID") DO NOTHING;


-- upgrade: the tasks that have fact documents are queued once (qtyUsed was connected after the first release); a second run only re-checks them - rows that did not change are not written
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT f."rowOwnerGUID", 'install' FROM public.task_fact_usage_timeline f
ON CONFLICT ("rowOwnerGUID") DO NOTHING;

-- upgrade: the tasks that have POSTED vendor invoices are queued once (the report gained the column VendorInvoiced = qtyVendorInvoiced) and, with the money column, Vendor Invoice / Sum = sumVendorInvoiced (every run of this file queues them again; the worker writes only the rows that changed)
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT s."rowOwnerGUID", 'install' FROM public.project_status_movements s WHERE s."rowMovementKind" = 'invoiced'
ON CONFLICT ("rowOwnerGUID") DO NOTHING;


-- upgrade: the tasks that have POSTED purchase orders are queued once (the report gained the column Ordered = qtyOrdered)
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT s."rowOwnerGUID", 'install' FROM public.project_status_movements s WHERE s."rowMovementKind" = 'ordered'
ON CONFLICT ("rowOwnerGUID") DO NOTHING;


-- upgrade: the tasks that have POSTED product receipts are queued once (the report gained the column Received = qtyReceived, PART 30)
INSERT INTO public.monitor01_dirty ("rowOwnerGUID", "reason")
SELECT DISTINCT s."rowOwnerGUID", 'install' FROM public.project_status_movements s WHERE s."rowMovementKind" = 'received'
ON CONFLICT ("rowOwnerGUID") DO NOTHING;


-- ---- pg_cron: the tick and the housekeeping of the Monitor01 worker are scheduled by start3_sql_pg_cron.sql (run it after this file; the install of this file does not need pg_cron). ----


NOTIFY pgrst, 'reload schema';
-- ===============================================================================================
-- PART 26: create_vendor_invoice.sql
-- the legal entity catalog (folders by country), the main vendor of partners / equipment / products, the VENDOR INVOICE document (one vendor + one contract), its posting into the project status register
-- ===============================================================================================


SELECT public.kit8_setup_def_table('legalEntityTable');


DO $$
DECLARE
  t text := 'legalEntityTable';
BEGIN
  EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (true)', t || '_select', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (true)', t || '_insert', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (true) WITH CHECK (true)', t || '_update', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (true)', t || '_delete', t);
END $$;


-- the folder is a country or 'empty'; a legal entity that a contract or an invoice uses is not deleted
CREATE OR REPLACE FUNCTION public.legal_entity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = public, extensions AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM public."contractTable" k WHERE k."rowJSON"->>'legalEntityGUID' = OLD."rowGUID")
       OR (to_regclass('public.vendor_invoice_header') IS NOT NULL AND EXISTS (SELECT 1 FROM public.vendor_invoice_header h WHERE h."rowOwnerGUID" = OLD."rowGUID"))
       OR (to_regclass('public.purchase_order_header') IS NOT NULL AND EXISTS (SELECT 1 FROM public.purchase_order_header h WHERE h."rowOwnerGUID" = OLD."rowGUID")) THEN
      RAISE EXCEPTION 'the legal entity is used by a contract, a vendor invoice or a purchase order: set it inactive instead' USING ERRCODE = '23503';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW."rowParentGUID" IS DISTINCT FROM 'empty' AND NOT EXISTS (SELECT 1 FROM public."countryTable" c WHERE c."rowGUID" = NEW."rowParentGUID") THEN
    RAISE EXCEPTION 'the folder of a legal entity is a country (countryTable) or empty, not %', NEW."rowParentGUID" USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_legal_entity_guard ON public."legalEntityTable";

CREATE TRIGGER trg_legal_entity_guard BEFORE INSERT OR UPDATE OR DELETE ON public."legalEntityTable" FOR EACH ROW EXECUTE FUNCTION public.legal_entity_guard();


-- contractTable.rowJSON.legalEntityGUID: optional, but an existing legal entity
CREATE OR REPLACE FUNCTION public.contract_legal_entity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = public, extensions AS $$
BEGIN
  IF NULLIF(NEW."rowJSON"->>'legalEntityGUID', '') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public."legalEntityTable" e WHERE e."rowGUID" = NEW."rowJSON"->>'legalEntityGUID') THEN
    RAISE EXCEPTION 'the legal entity % of the contract does not exist', NEW."rowJSON"->>'legalEntityGUID' USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_contract_legal_entity_guard ON public."contractTable";

CREATE TRIGGER trg_contract_legal_entity_guard BEFORE INSERT OR UPDATE OF "rowJSON" ON public."contractTable" FOR EACH ROW EXECUTE FUNCTION public.contract_legal_entity_guard();


-- ---- the MAIN VENDOR of a partner / equipment / product -----------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.main_vendor_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE
  v text := NULLIF(NEW."rowJSON"->>'mainVendorGUID', '');
  c text := NULLIF(NEW."rowJSON"->>'mainVendorContractGUID', '');
BEGIN
  IF v IS NULL AND c IS NULL THEN RETURN NEW; END IF;
  IF v IS NULL THEN
    RAISE EXCEPTION 'mainVendorContractGUID needs mainVendorGUID' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'partnerTable' AND v = NEW."rowGUID" THEN
    RAISE EXCEPTION 'a partner cannot be its own main vendor' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public."partnerTable" p WHERE p."rowGUID" = v) THEN
    RAISE EXCEPTION 'the main vendor % is not a partner', v USING ERRCODE = '23503';
  END IF;
  IF c IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public."contractTable" k WHERE k."rowGUID" = c AND k."rowParentGUID" = 'partner' AND k."rowOwnerGUID" = v) THEN
    RAISE EXCEPTION 'the main vendor contract % is not a contract of the main vendor %', c, v USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_main_vendor_guard ON public."partnerTable";

CREATE TRIGGER trg_main_vendor_guard BEFORE INSERT OR UPDATE OF "rowJSON" ON public."partnerTable" FOR EACH ROW EXECUTE FUNCTION public.main_vendor_guard();

DROP TRIGGER IF EXISTS trg_main_vendor_guard ON public."equipmentTable";

CREATE TRIGGER trg_main_vendor_guard BEFORE INSERT OR UPDATE OF "rowJSON" ON public."equipmentTable" FOR EACH ROW EXECUTE FUNCTION public.main_vendor_guard();

DROP TRIGGER IF EXISTS trg_main_vendor_guard ON public."productTable";

CREATE TRIGGER trg_main_vendor_guard BEFORE INSERT OR UPDATE OF "rowJSON" ON public."productTable" FOR EACH ROW EXECUTE FUNCTION public.main_vendor_guard();

DROP TRIGGER IF EXISTS trg_vendor_invoice_header_touch ON public.vendor_invoice_header;

CREATE TRIGGER trg_vendor_invoice_header_touch BEFORE UPDATE ON public.vendor_invoice_header FOR EACH ROW EXECUTE FUNCTION public.pm_touch_updated_at();

DROP TRIGGER IF EXISTS trg_vendor_invoice_lines_touch ON public.vendor_invoice_lines;

CREATE TRIGGER trg_vendor_invoice_lines_touch BEFORE UPDATE ON public.vendor_invoice_lines FOR EACH ROW EXECUTE FUNCTION public.pm_touch_updated_at();


-- the state of a document for the policies: 'draft' | 'posted' (NULL = no such document in MY organization)
CREATE OR REPLACE FUNCTION public.vendor_invoice_state(p_header uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT CASE WHEN COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN 'posted' ELSE 'draft' END
    FROM public.vendor_invoice_header h
   WHERE h."rowGUID" = p_header AND h."rowOrganizationGUID" = public.organization_of_current_user();
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_state(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_state(uuid) TO authenticated;


-- ---- the VAT basis (documentation/VENDOR_INVOICE_DOC.html) ------------------------------------------------------------------------------------------------------------------
-- Every money amount is stored as COMPONENTS: net, VAT, and the part of the VAT that is cost (not recoverable). A report shows ONE of three bases through this function:
--   'cost'  = net + the VAT that is cost (the IFRS / GAAP cost; default)  ·  'net' = net  ·  'gross' = net + all VAT (With VAT)
CREATE OR REPLACE FUNCTION public.vat_basis_amount(p_net numeric, p_vat numeric, p_vat_in_cost numeric, p_basis text) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF p_basis = 'cost' THEN RETURN COALESCE(p_net, 0) + COALESCE(p_vat_in_cost, 0);
  ELSIF p_basis = 'net' THEN RETURN COALESCE(p_net, 0);
  ELSIF p_basis = 'gross' THEN RETURN COALESCE(p_net, 0) + COALESCE(p_vat, 0);
  END IF;
  RAISE EXCEPTION 'vat_basis_amount: the basis must be cost, net or gross, not %', p_basis USING ERRCODE = '22023';
END;
$$;

GRANT EXECUTE ON FUNCTION public.vat_basis_amount(numeric, numeric, numeric, text) TO authenticated;


-- a row of valueAddedTaxTable: its percent and the share of it that can be recovered (rowJSON.vatRecoverablePercent, missing = 100). NULL percent = no such rate.
CREATE OR REPLACE FUNCTION public.vat_rate_lookup(p_guid text, OUT o_percent numeric, OUT o_recoverable numeric)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT CASE WHEN v."rowJSON"->>'vatTablePercent' ~ '^[0-9]+(\.[0-9]+)?$' THEN (v."rowJSON"->>'vatTablePercent')::numeric END,
         CASE WHEN v."rowJSON"->>'vatRecoverablePercent' ~ '^[0-9]+(\.[0-9]+)?$' THEN LEAST(100, (v."rowJSON"->>'vatRecoverablePercent')::numeric) ELSE 100 END
    FROM public."valueAddedTaxTable" v WHERE v."rowGUID" = p_guid
$$;

REVOKE ALL ON FUNCTION public.vat_rate_lookup(text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vat_rate_lookup(text) TO authenticated;


-- THE calculation of a document line (the four triggers call it): qty x price x VAT % -> the contract sums -> the budget and accounting sums (at the rate of the plan of the line) and the other way
-- round: the user may type the accounting sum before VAT (the PRICE is calculated back) or the accounting VAT (the VAT % is calculated, the price stays).
--   p_in_before / p_in_vatacc = the values of the row being saved; p_old_* = the values of the row before (UPDATE) - a typed accounting value is recognized by "the quantity, the price and the VAT %
--   did not change but the accounting value did". A change of the quantity, the price or the VAT % calculates everything again (a typed value is dropped).
--   p_customer: the VAT of a customer invoice is never cost (IFRS 15: collected for the tax authority).
CREATE OR REPLACE FUNCTION public.vat_line_calc(
  p_qty numeric, p_price numeric, p_vat numeric, p_json jsonb, p_customer boolean,
  p_is_update boolean, p_old_qty numeric, p_old_price numeric, p_old_vat numeric, p_old_before numeric, p_old_vatacc numeric,
  p_in_before numeric, p_in_vatacc numeric, p_what text,
  OUT o_price numeric, OUT o_vat numeric, OUT o_vat_custom boolean,
  OUT o_contract numeric, OUT o_vat_contract numeric,
  OUT o_budget numeric, OUT o_vat_budget numeric, OUT o_in_cost_budget numeric,
  OUT o_acc_before numeric, OUT o_acc_vat numeric, OUT o_acc_total numeric, OUT o_in_cost_acc numeric)
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  v_pp numeric; v_ub numeric; v_ua numeric; v_share numeric; v_rate boolean; v_mb boolean; v_mv boolean; v_before numeric;
BEGIN
  v_pp := CASE WHEN jsonb_typeof(p_json->'priceTaskLine') = 'number' THEN (p_json->>'priceTaskLine')::numeric END;
  v_ub := CASE WHEN jsonb_typeof(p_json->'unitSumForBudget') = 'number' THEN (p_json->>'unitSumForBudget')::numeric END;
  v_ua := CASE WHEN jsonb_typeof(p_json->'unitSumForAccounting') = 'number' THEN (p_json->>'unitSumForAccounting')::numeric END;
  v_share := CASE WHEN p_customer THEN 0
                  ELSE 1 - LEAST(100, GREATEST(0, CASE WHEN jsonb_typeof(p_json->'vatRecoverablePercent') = 'number' THEN (p_json->>'vatRecoverablePercent')::numeric ELSE 100 END)) / 100 END;
  v_rate := v_ua IS NOT NULL AND v_pp IS NOT NULL AND v_pp > 0;
  o_price := p_price; o_vat := p_vat; o_vat_custom := false;

  v_mb := p_is_update AND p_in_before IS NOT NULL AND p_qty IS NOT DISTINCT FROM p_old_qty AND p_price IS NOT DISTINCT FROM p_old_price AND p_vat IS NOT DISTINCT FROM p_old_vat
          AND p_in_before IS DISTINCT FROM p_old_before;
  v_mv := p_is_update AND p_in_vatacc IS NOT NULL AND p_qty IS NOT DISTINCT FROM p_old_qty AND p_price IS NOT DISTINCT FROM p_old_price AND p_vat IS NOT DISTINCT FROM p_old_vat
          AND p_in_vatacc IS DISTINCT FROM p_old_vatacc;
  IF (v_mb OR v_mv) AND NOT v_rate THEN
    RAISE EXCEPTION '%: this line has no plan rate (a plan price and a unit sum), so the accounting sums cannot be typed', p_what USING ERRCODE = '23514';
  END IF;

  IF v_mb THEN
    IF COALESCE(p_qty, 0) = 0 OR v_ua = 0 THEN
      RAISE EXCEPTION '%: the price cannot be calculated from the accounting sum (the quantity or the unit sum is 0)', p_what USING ERRCODE = '23514';
    END IF;
    o_price := round(p_in_before * v_pp / v_ua / p_qty, 4);
  END IF;
  IF v_mv THEN
    v_before := CASE WHEN v_mb THEN p_in_before ELSE COALESCE(p_in_before, round(round(p_qty * o_price, 2) * v_ua / v_pp, 2)) END;
    IF v_before IS NULL OR v_before <= 0 THEN
      RAISE EXCEPTION '%: the VAT %% cannot be calculated from a zero accounting sum', p_what USING ERRCODE = '23514';
    END IF;
    o_vat := round(p_in_vatacc / v_before * 100, 3);
    IF o_vat > 100 THEN RAISE EXCEPTION '%: the VAT would be above 100 %% of the sum', p_what USING ERRCODE = '23514'; END IF;
    o_vat_custom := true;
  END IF;

  o_contract := round(p_qty * o_price, 2);
  o_vat_contract := round(o_contract * o_vat / 100, 2);
  IF v_ub IS NULL THEN o_budget := NULL; o_vat_budget := NULL;
  ELSIF v_pp IS NOT NULL AND v_pp > 0 THEN o_budget := round(o_contract * v_ub / v_pp, 2); o_vat_budget := round(o_vat_contract * v_ub / v_pp, 2);
  ELSE o_budget := round(p_qty * v_ub, 2); o_vat_budget := round(o_budget * o_vat / 100, 2); END IF;
  IF v_ua IS NULL THEN o_acc_before := NULL; o_acc_vat := NULL;
  ELSIF v_pp IS NOT NULL AND v_pp > 0 THEN o_acc_before := round(o_contract * v_ua / v_pp, 2); o_acc_vat := round(o_vat_contract * v_ua / v_pp, 2);
  ELSE o_acc_before := round(p_qty * v_ua, 2); o_acc_vat := round(o_acc_before * o_vat / 100, 2); END IF;
  IF v_mb THEN o_acc_before := p_in_before; END IF;                  -- a typed value stays as typed
  IF v_mv THEN o_acc_vat := p_in_vatacc; END IF;
  o_acc_total := CASE WHEN o_acc_before IS NULL THEN NULL ELSE o_acc_before + COALESCE(o_acc_vat, 0) END;
  o_in_cost_budget := CASE WHEN o_vat_budget IS NULL THEN NULL ELSE round(o_vat_budget * v_share, 2) END;
  o_in_cost_acc    := CASE WHEN o_acc_vat IS NULL THEN NULL ELSE round(o_acc_vat * v_share, 2) END;
END;
$$;


-- one line: the project / task are the ones of the task line, the sums follow the quantity, the price and the VAT % the user states (the budget / accounting sums by the ratio of the task line)
CREATE OR REPLACE FUNCTION public.vendor_invoice_lines_before_write() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE
  v_rate record; v_calc record; v_o_qty numeric; v_o_price numeric; v_o_vat numeric; v_o_before numeric; v_o_vatacc numeric;
BEGIN
  IF COALESCE(current_setting('app.vat_backfill', true), '') = 'on' THEN RETURN NEW; END IF;      -- the one-time backfill of start2 sets the columns itself
  IF TG_OP = 'UPDATE' THEN
    v_o_qty := OLD."qtyInvoiced"; v_o_price := OLD."priceInvoiced"; v_o_vat := OLD."vatRatioInvoiced"; v_o_before := OLD."sumForAccountingBeforeVAT"; v_o_vatacc := OLD."sumForAccountingVAT";
    -- the identity of a line is frozen: only the quantity, the price, the VAT % and the order change (an independent line also its role, resource, unit).
    -- vendor_invoice_set_line_task (a MULTI PROJECT invoice) moves a line to another task / task line: it opens the gate for its own statement only
    IF NEW."rowHeaderGUID" IS DISTINCT FROM OLD."rowHeaderGUID" THEN
      RAISE EXCEPTION 'vendor invoice: only the quantity, the price and the VAT %% of a line can be changed' USING ERRCODE = '23514';
    END IF;
    IF COALESCE(current_setting('app.vendor_invoice_line_move', true), '') <> 'on' AND (
       NEW."rowProjectGUID" IS DISTINCT FROM OLD."rowProjectGUID" OR NEW."rowOwnerGUID" IS DISTINCT FROM OLD."rowOwnerGUID"
       OR NEW."genusGUID" IS DISTINCT FROM OLD."genusGUID"
       OR ((NEW."rowJSON" - '{vatRateGUID,vatTablePercent,vatRecoverablePercent}'::text[]) IS DISTINCT FROM (OLD."rowJSON" - '{vatRateGUID,vatTablePercent,vatRecoverablePercent}'::text[]) AND OLD."taskLineGUID" IS NOT NULL)     -- a line that came from a task line is described by it; an INDEPENDENT line (no task line) is described here
       OR (NEW."taskLineGUID" IS DISTINCT FROM OLD."taskLineGUID" AND NEW."taskLineGUID" IS NOT NULL)) THEN
      RAISE EXCEPTION 'vendor invoice: only the quantity, the price and the VAT %% of a line can be changed' USING ERRCODE = '23514';
    END IF;
  END IF;
  -- the VAT rate chosen from valueAddedTaxTable (rowJSON.vatRateGUID): its percent and its recoverable share go into the line
  IF NEW."rowJSON"->>'vatRateGUID' IS NOT NULL AND (TG_OP = 'INSERT' OR NEW."rowJSON"->>'vatRateGUID' IS DISTINCT FROM OLD."rowJSON"->>'vatRateGUID') THEN
    SELECT * INTO v_rate FROM public.vat_rate_lookup(NEW."rowJSON"->>'vatRateGUID');
    IF v_rate.o_percent IS NULL THEN
      RAISE EXCEPTION 'vendor invoice: the VAT rate does not exist' USING ERRCODE = '23514';
    END IF;
    NEW."vatRatioInvoiced" := v_rate.o_percent;
    NEW."rowJSON" := NEW."rowJSON" || jsonb_build_object('vatTablePercent', v_rate.o_percent, 'vatRecoverablePercent', v_rate.o_recoverable);
  END IF;
  -- the sums (documentation/VENDOR_INVOICE_DOC.html sections 8, 9): price -> contract sums -> budget / accounting sums, or a typed accounting sum -> the price / the VAT %
  SELECT * INTO v_calc FROM public.vat_line_calc(NEW."qtyInvoiced", NEW."priceInvoiced", NEW."vatRatioInvoiced", NEW."rowJSON", false, TG_OP = 'UPDATE', v_o_qty, v_o_price, v_o_vat, v_o_before, v_o_vatacc,
                                                  NEW."sumForAccountingBeforeVAT", NEW."sumForAccountingVAT", 'vendor invoice');
  NEW."priceInvoiced" := v_calc.o_price;
  NEW."vatRatioInvoiced" := v_calc.o_vat;
  IF v_calc.o_vat_custom THEN NEW."rowJSON" := NEW."rowJSON" - 'vatRateGUID' - 'vatTablePercent'; END IF;
  NEW."sumForContract" := v_calc.o_contract;
  NEW."vatForContract" := v_calc.o_vat_contract;
  NEW."sumForBudget" := v_calc.o_budget;
  NEW."vatForBudget" := v_calc.o_vat_budget;
  NEW."vatInCostForBudget" := v_calc.o_in_cost_budget;
  NEW."sumForAccountingBeforeVAT" := v_calc.o_acc_before;
  NEW."sumForAccountingVAT" := v_calc.o_acc_vat;
  NEW."sumForAccounting" := v_calc.o_acc_total;           -- on a LINE: the total with VAT (the register gets the two parts)
  NEW."vatForAccounting" := v_calc.o_acc_vat;
  NEW."vatInCostForAccounting" := v_calc.o_in_cost_acc;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_vendor_invoice_lines_before_write ON public.vendor_invoice_lines;

CREATE TRIGGER trg_vendor_invoice_lines_before_write BEFORE INSERT OR UPDATE ON public.vendor_invoice_lines FOR EACH ROW EXECUTE FUNCTION public.vendor_invoice_lines_before_write();


-- the header: the organization of the writer, the folder (legal entity + partner) and the currency of the contract are derived. The vendor and the contract of an UNPOSTED document can be changed
-- (vendor_invoice_set_header; a draft made from lines without a vendor has none yet); a POSTED document keeps them and needs its vendor and its legal entity
CREATE OR REPLACE FUNCTION public.vendor_invoice_header_before_write() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE
  v_partner text := NULLIF(NEW."rowJSON"->>'vendorInvoicePartner', '');
  v_contract text := NULLIF(NEW."rowJSON"->>'vendorInvoiceContract', '');
  v_status text := COALESCE(NEW."rowJSON"->'documentHeader'->>'documentStatus', 'draft');
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."rowOrganizationGUID" := public.organization_of_current_user();
    IF NEW."rowOrganizationGUID" IS NULL THEN
      RAISE EXCEPTION 'the user has no organization' USING ERRCODE = '42501';
    END IF;
  ELSE
    NEW."rowOrganizationGUID" := OLD."rowOrganizationGUID";
    IF COALESCE(OLD."rowJSON"->'documentHeader'->>'documentStatus', 'draft') <> 'draft'
       AND (v_partner IS DISTINCT FROM NULLIF(OLD."rowJSON"->>'vendorInvoicePartner', '') OR v_contract IS DISTINCT FROM NULLIF(OLD."rowJSON"->>'vendorInvoiceContract', '')) THEN
      RAISE EXCEPTION 'the vendor and the contract of a POSTED vendor invoice cannot be changed: unpost it first' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF v_status <> 'draft' AND v_partner IS NULL THEN
    RAISE EXCEPTION 'a posted vendor invoice needs its vendor (vendorInvoicePartner)' USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' AND NEW."rowOwnerGUID" IS NULL THEN
    RAISE EXCEPTION 'a posted vendor invoice needs its legal entity' USING ERRCODE = '23514';
  END IF;
  IF v_partner IS NULL AND v_contract IS NOT NULL THEN
    RAISE EXCEPTION 'a contract needs its vendor' USING ERRCODE = '23514';
  END IF;
  IF v_partner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public."partnerTable" p WHERE p."rowGUID" = v_partner) THEN
    RAISE EXCEPTION 'the vendor % is not a partner', v_partner USING ERRCODE = '23503';
  END IF;
  IF v_contract IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public."contractTable" k WHERE k."rowGUID" = v_contract AND k."rowParentGUID" = 'partner' AND k."rowOwnerGUID" = v_partner) THEN
    RAISE EXCEPTION 'the contract % is not a contract of the vendor %', v_contract, v_partner USING ERRCODE = '23514';
  END IF;
  NEW."rowJSON" := jsonb_set(jsonb_set(NEW."rowJSON", '{vendorInvoiceFolder}', to_jsonb(COALESCE(NEW."rowOwnerGUID", 'empty') || ':' || COALESCE(v_partner, 'empty'))),
                             '{vendorInvoiceCurrency}', to_jsonb(COALESCE((SELECT NULLIF(k."rowJSON"->>'contractCurrency', '') FROM public."contractTable" k WHERE k."rowGUID" = v_contract), '')));
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_vendor_invoice_header_before_write ON public.vendor_invoice_header;

CREATE TRIGGER trg_vendor_invoice_header_before_write BEFORE INSERT OR UPDATE ON public.vendor_invoice_header FOR EACH ROW EXECUTE FUNCTION public.vendor_invoice_header_before_write();


-- policies: the header is read by the organization and written ONLY by the RPCs (a draft can also be deleted directly); the lines are read by the organization, the quantity / price / VAT % of a line of a DRAFT are updated and a line is deleted by the owner of its project
ALTER TABLE public.vendor_invoice_header REPLICA IDENTITY FULL;

ALTER TABLE public.vendor_invoice_header ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.vendor_invoice_header FROM anon, authenticated;

GRANT SELECT, DELETE ON public.vendor_invoice_header TO authenticated;

DROP POLICY IF EXISTS vendor_invoice_header_select ON public.vendor_invoice_header;

CREATE POLICY vendor_invoice_header_select ON public.vendor_invoice_header FOR SELECT TO authenticated USING ("rowOrganizationGUID" = public.organization_of_current_user());

-- a DRAFT of the organization can be deleted directly (the table of the list does it; its lines go with it); a posted one never
DROP POLICY IF EXISTS vendor_invoice_header_delete ON public.vendor_invoice_header;

CREATE POLICY vendor_invoice_header_delete ON public.vendor_invoice_header FOR DELETE TO authenticated
  USING ("rowOrganizationGUID" = public.organization_of_current_user() AND COALESCE("rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'draft');

ALTER TABLE public.vendor_invoice_lines REPLICA IDENTITY FULL;

ALTER TABLE public.vendor_invoice_lines ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.vendor_invoice_lines FROM anon, authenticated;

GRANT SELECT, UPDATE, DELETE ON public.vendor_invoice_lines TO authenticated;

DROP POLICY IF EXISTS vendor_invoice_lines_select ON public.vendor_invoice_lines;

CREATE POLICY vendor_invoice_lines_select ON public.vendor_invoice_lines FOR SELECT TO authenticated USING (public.vendor_invoice_state("rowHeaderGUID") IS NOT NULL);

DROP POLICY IF EXISTS vendor_invoice_lines_update ON public.vendor_invoice_lines;

CREATE POLICY vendor_invoice_lines_update ON public.vendor_invoice_lines FOR UPDATE TO authenticated
  USING (public.vendor_invoice_state("rowHeaderGUID") = 'draft' AND public.pm_owns_project("rowProjectGUID"))
  WITH CHECK (public.vendor_invoice_state("rowHeaderGUID") = 'draft' AND public.pm_owns_project("rowProjectGUID"));

DROP POLICY IF EXISTS vendor_invoice_lines_delete ON public.vendor_invoice_lines;

CREATE POLICY vendor_invoice_lines_delete ON public.vendor_invoice_lines FOR DELETE TO authenticated
  USING (public.vendor_invoice_state("rowHeaderGUID") = 'draft' AND public.pm_owns_project("rowProjectGUID"));


-- realtime: the documents and their lines (the legal entities too)
DO $$
DECLARE
  v_all boolean; t text;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all THEN
    FOREACH t IN ARRAY ARRAY['vendor_invoice_header', 'vendor_invoice_lines', 'legalEntityTable'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
      END IF;
    END LOOP;
  END IF;
END $$;


-- ---- the register: a POSTED vendor invoice = 'invoiced' movements (registrator = the document, type vendorInvoiceHeader) --------------------------------------------------------
CREATE OR REPLACE FUNCTION public.project_status_register_invoice(p_header uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v integer := 0;
BEGIN
  DELETE FROM public.project_status_movements s WHERE s."rowRegistratorGUID" = p_header;
  INSERT INTO public.project_status_movements ("rowMovementKind", "rowTurnoverMoment", "rowTurnoverDay", "rowRegistratorGUID", "rowRegistratorType", "rowProjectTaskLineGUID", "rowProjectGUID", "rowOwnerGUID", "rowOwnerUserGUID",
         "genusGUID", "resourceRoleGUID", "measureUnit", "businessUnitGUID", "partnerGUID", "contractGUID", "legalEntityGUID",
         "qtyProjectStatus", "sumForBudget", "sumForContract", "vatForContract", "sumForAccounting", "vatForAccounting", "vatForBudget", "vatInCostForBudget", "vatInCostForAccounting")
  SELECT 'invoiced', COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '')::timestamptz, h."created_at"),
         ((COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '')::timestamptz, h."created_at") + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date,
         h."rowGUID", 'vendorInvoiceHeader', l."taskLineGUID", l."rowProjectGUID", l."rowOwnerGUID", p."rowOwnerGUID",
         l."genusGUID", COALESCE(l."rowJSON"->>'resourceRoleItem', ''), COALESCE(l."rowJSON"->>'measureUnitTaskLine', ''), NULLIF(l."rowJSON"->>'businessUnitTaskLine', ''),
         NULLIF(h."rowJSON"->>'vendorInvoicePartner', ''), NULLIF(h."rowJSON"->>'vendorInvoiceContract', ''), h."rowOwnerGUID",
         COALESCE(l."qtyInvoiced", 0), COALESCE(l."sumForBudget", 0), COALESCE(l."sumForContract", 0), COALESCE(l."vatForContract", 0), COALESCE(l."sumForAccountingBeforeVAT", 0), COALESCE(l."sumForAccountingVAT", 0), COALESCE(l."vatForBudget", 0), COALESCE(l."vatInCostForBudget", 0), COALESCE(l."vatInCostForAccounting", 0)
    FROM public.vendor_invoice_header h
    JOIN public.vendor_invoice_lines l ON l."rowHeaderGUID" = h."rowGUID"
    JOIN public.project_table p ON p."rowGUID" = l."rowProjectGUID"
   WHERE h."rowGUID" = p_header AND COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted';
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.project_status_register_invoice(uuid) FROM PUBLIC, anon, authenticated;


-- a project switch of the Vendor tab (project_table.rowJSON): true while it was never saved (the settings default to true), false only when it is stored false
CREATE OR REPLACE FUNCTION public.vendor_project_setting(p_project uuid, p_key text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT COALESCE((SELECT p."rowJSON"->>p_key FROM public.project_table p WHERE p."rowGUID" = p_project), 'true') <> 'false';
$$;

REVOKE ALL ON FUNCTION public.vendor_project_setting(uuid, text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_project_setting(uuid, text) TO authenticated;


-- ---- vendor_invoice_candidates(task, lines): the vendors (and their contracts) of the task lines ---------------------------------------------------------------------------
-- A line's vendor: the partner of the contract selected on the line (Time: taskResourceContract, Material / Expense: taskLinePartnerContract); else the partner of the line (taskLinePartnerItem);
-- else the MAIN VENDOR of its resource (equipment of a Time line, product of a Material line) with the main vendor contract; a WORK CENTER (PART 35): a Partner work center IS the supplier (its partner), an
-- Equipment work center has the main vendor of its equipment, a Person work center none. A line without a vendor is counted in "skipped" and listed in "skippedLineGUIDs"
-- (create_vendor_invoices makes ONE draft without a vendor of them: the vendor is chosen in the form).
CREATE OR REPLACE FUNCTION public.vendor_invoice_candidates(p_task uuid, p_lines uuid[] DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_project uuid; v_rows jsonb; v_skipped integer; v_skipped_lines jsonb; v_free boolean;
BEGIN
  SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = p_task;
  IF v_project IS NULL THEN
    RAISE EXCEPTION 'task % does not exist', p_task USING ERRCODE = '23503';
  END IF;
  IF NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'not your project' USING ERRCODE = '42501';
  END IF;
  WITH ln AS (
    SELECT l."rowGUID" AS line, l."rowParentGUID" AS genus,
           NULLIF(CASE WHEN l."rowParentGUID" = 'timeGenus' THEN l."rowJSON"->>'taskResourceContract' ELSE l."rowJSON"->>'taskLinePartnerContract' END, '') AS line_contract,
           NULLIF(l."rowJSON"->>'taskLinePartnerItem', '') AS line_partner,
           NULLIF(l."rowJSON"->>'taskResourceItem', '') AS res,
           NULLIF(l."rowJSON"->>'taskResourceKind', '') AS kind
      FROM public.task_line_table l
     WHERE l."rowOwnerGUID" = p_task AND l."rowParentGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus') AND (p_lines IS NULL OR l."rowGUID" = ANY (p_lines))
  ), mv AS (
    SELECT ln.*, k."rowGUID" AS k_guid, k."rowOwnerGUID" AS k_partner,
           NULLIF(CASE WHEN ln.genus = 'timeGenus' AND ln.kind = 'equipment' THEN e."rowJSON"->>'mainVendorGUID'
                       WHEN ln.genus = 'timeGenus' AND ln.kind = 'workCenter' THEN CASE wc."rowJSON"->>'workCenterKind' WHEN 'partner' THEN wc."rowJSON"->>'workCenterBase' WHEN 'equipment' THEN we."rowJSON"->>'mainVendorGUID' END
                       WHEN ln.genus = 'materialGenus' THEN pr."rowJSON"->>'mainVendorGUID' END, '') AS mv_vendor,
           NULLIF(CASE WHEN ln.genus = 'timeGenus' AND ln.kind = 'equipment' THEN e."rowJSON"->>'mainVendorContractGUID'
                       WHEN ln.genus = 'timeGenus' AND ln.kind = 'workCenter' THEN CASE WHEN wc."rowJSON"->>'workCenterKind' = 'equipment' THEN we."rowJSON"->>'mainVendorContractGUID' END
                       WHEN ln.genus = 'materialGenus' THEN pr."rowJSON"->>'mainVendorContractGUID' END, '') AS mv_contract
      FROM ln
      LEFT JOIN public."contractTable" k ON k."rowGUID" = ln.line_contract AND k."rowParentGUID" = 'partner'
      LEFT JOIN public."equipmentTable" e ON ln.genus = 'timeGenus' AND ln.kind = 'equipment' AND e."rowGUID" = ln.res
      LEFT JOIN public."workCenterTable" wc ON ln.genus = 'timeGenus' AND ln.kind = 'workCenter' AND wc."rowGUID" = ln.res
      LEFT JOIN public."equipmentTable" we ON wc."rowJSON"->>'workCenterKind' = 'equipment' AND we."rowGUID" = wc."rowJSON"->>'workCenterBase'
      LEFT JOIN public."productTable" pr ON ln.genus = 'materialGenus' AND pr."rowGUID" = ln.res
  ), res AS (
    SELECT mv.line,
           CASE WHEN mv.k_guid IS NOT NULL THEN mv.k_partner ELSE COALESCE(mv.line_partner, mv.mv_vendor) END AS partner,
           CASE WHEN mv.k_guid IS NOT NULL THEN mv.k_guid WHEN COALESCE(mv.line_partner, mv.mv_vendor) = mv.mv_vendor THEN mv.mv_contract END AS contract
      FROM mv
  ), grp AS (
    SELECT r.partner, r.contract, array_agg(r.line ORDER BY r.line) AS lines
      FROM res r WHERE r.partner IS NOT NULL GROUP BY r.partner, r.contract
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'partnerGUID', g.partner, 'partnerTitle', COALESCE(pt."rowJSON"->>'partnerTitle', g.partner),
           'contractGUID', g.contract, 'contractInfo', NULLIF(btrim(concat_ws(' · ', ck."rowJSON"->>'contractNumber', ck."rowJSON"->>'contractTitle')), ''),
           'contractCurrency', NULLIF(ck."rowJSON"->>'contractCurrency', ''), 'legalEntityGUID', NULLIF(ck."rowJSON"->>'legalEntityGUID', ''),
           'lineCount', cardinality(g.lines), 'lineGUIDs', to_jsonb(g.lines)) ORDER BY COALESCE(pt."rowJSON"->>'partnerTitle', g.partner), g.contract NULLS FIRST), '[]'::jsonb),
         (SELECT count(*) FROM res WHERE res.partner IS NULL),
         (SELECT COALESCE(jsonb_agg(res.line ORDER BY res.line), '[]'::jsonb) FROM res WHERE res.partner IS NULL)
    INTO v_rows, v_skipped, v_skipped_lines
    FROM grp g
    LEFT JOIN public."partnerTable" pt ON pt."rowGUID" = g.partner
    LEFT JOIN public."contractTable" ck ON ck."rowGUID" = g.contract;
  v_free := public.vendor_project_setting(v_project, 'userCanCreateVendorInvoicesFromTasksWithEmptyVendors');
  RETURN jsonb_build_object('rows', v_rows, 'skipped', COALESCE(v_skipped, 0), 'skippedLineGUIDs', CASE WHEN v_free THEN COALESCE(v_skipped_lines, '[]'::jsonb) ELSE '[]'::jsonb END, 'noVendorAllowed', v_free);
END;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_candidates(uuid, uuid[]) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_candidates(uuid, uuid[]) TO authenticated;


-- ---- create_vendor_invoices(task, selection, legal entity): ONE draft document per selected (vendor, contract) -----------------------------------------------------------------
-- selection = [{ partnerGUID | null, contractGUID | null, lineGUIDs: [...] }]; a null partner = a draft WITHOUT a vendor (and, when no legal entity is given, without one): both are chosen in the form before Post. The lines come from the task lines; the quantity starts as what is NOT invoiced yet (plan - the quantity on the vendor invoice lines),
-- the price and the VAT % of the task line. The legal entity: the one given, else the one of the contract; a document without any quantity left is not made.
CREATE OR REPLACE FUNCTION public.create_vendor_invoices(p_task uuid, p_selection jsonb, p_legal_entity text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_project uuid; v_sel jsonb; v_partner text; v_contract text; v_lines uuid[]; v_le text; v_header uuid; v_n integer; v_free boolean;
  v_docs jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb;
BEGIN
  SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = p_task;
  IF v_project IS NULL THEN
    RAISE EXCEPTION 'task % does not exist', p_task USING ERRCODE = '23503';
  END IF;
  IF NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'not your project' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_selection) <> 'array' OR jsonb_array_length(p_selection) = 0 THEN
    RAISE EXCEPTION 'select at least one vendor' USING ERRCODE = '22023';
  END IF;
  v_free := public.vendor_project_setting(v_project, 'userCanCreateVendorInvoicesFromTasksWithEmptyVendors');
  FOR v_sel IN SELECT * FROM jsonb_array_elements(p_selection) LOOP
    v_partner := NULLIF(v_sel->>'partnerGUID', '');
    v_contract := NULLIF(v_sel->>'contractGUID', '');
    SELECT COALESCE(array_agg(x::uuid), ARRAY[]::uuid[]) INTO v_lines FROM jsonb_array_elements_text(COALESCE(v_sel->'lineGUIDs', '[]'::jsonb)) x;
    IF v_partner IS NULL AND v_contract IS NOT NULL THEN
      RAISE EXCEPTION 'a contract needs its vendor' USING ERRCODE = '22023';
    END IF;
    IF v_partner IS NULL AND NOT v_free THEN
      RAISE EXCEPTION 'a vendor invoice without a vendor is switched off in the project settings (Vendor)' USING ERRCODE = '23514';
    END IF;
    v_le := COALESCE(NULLIF(p_legal_entity, ''), (SELECT NULLIF(k."rowJSON"->>'legalEntityGUID', '') FROM public."contractTable" k WHERE k."rowGUID" = v_contract));
    IF v_le IS NULL AND v_partner IS NOT NULL THEN
      RAISE EXCEPTION 'choose the legal entity of the invoice (the contract has none)' USING ERRCODE = '22023';
    END IF;
    v_header := gen_random_uuid();
    INSERT INTO public.vendor_invoice_header ("rowGUID", "rowOwnerGUID", "rowOrganizationGUID", "rowJSON")
    VALUES (v_header, v_le, 'x', jsonb_strip_nulls(jsonb_build_object(
              'documentHeader', jsonb_build_object('activeUser', public.app_user_guid(), 'documentNumber', 'VI-' || lpad(nextval('public.vendor_invoice_document_seq')::text, 5, '0'),
                                                    'documentStatus', 'draft', 'created_at', to_jsonb(clock_timestamp())),
              'vendorInvoicePartner', v_partner, 'vendorInvoiceContract', v_contract, 'vendorInvoiceTask', p_task, 'vendorInvoiceProject', v_project,
              'vendorInvoiceDateTime', to_jsonb(date_trunc('day', NOW())), 'vendorInvoiceNumber', '')));
    INSERT INTO public.vendor_invoice_lines ("rowHeaderGUID", "rowProjectGUID", "rowOwnerGUID", "taskLineGUID", "genusGUID", "orderInList", "qtyInvoiced", "priceInvoiced", "vatRatioInvoiced", "rowJSON")
    SELECT v_header, l."rowProjectGUID", l."rowOwnerGUID", l."rowGUID", l."rowParentGUID", (row_number() OVER (ORDER BY g.ord, l."orderInList", l."created_at"))::numeric,
           rest.qty,
           CASE WHEN jsonb_typeof(l."rowJSON"->'priceTaskLine') = 'number' THEN round((l."rowJSON"->>'priceTaskLine')::numeric, 4) ELSE 0 END,
           CASE WHEN jsonb_typeof(l."rowJSON"->'vatRatioTaskLine') = 'number' THEN least(greatest((l."rowJSON"->>'vatRatioTaskLine')::numeric, 0), 100) ELSE 0 END,
           jsonb_strip_nulls(jsonb_build_object(
             'resourceRoleItem',     NULLIF(l."rowJSON"->>'resourceRoleItem', ''),
             'taskResourceItem',     NULLIF(l."rowJSON"->>'taskResourceItem', ''),
             'taskResourceKind',     NULLIF(l."rowJSON"->>'taskResourceKind', ''),
             'measureUnitTaskLine',  NULLIF(l."rowJSON"->>'measureUnitTaskLine', ''),
             'budgetItemTaskLine',   NULLIF(l."rowJSON"->>'budgetItemTaskLine', ''),
             'businessUnitTaskLine', NULLIF(l."rowJSON"->>'businessUnitTaskLine', ''),
             'priceTaskLine',        CASE WHEN jsonb_typeof(l."rowJSON"->'priceTaskLine') = 'number' THEN l."rowJSON"->'priceTaskLine' END,
             'unitSumForAccounting', CASE WHEN jsonb_typeof(l."rowJSON"->'sumForAccounting') = 'number' AND jsonb_typeof(l."rowJSON"->'qtyTaskLine') = 'number' AND (l."rowJSON"->>'qtyTaskLine')::numeric > 0
                                          THEN to_jsonb(round((l."rowJSON"->>'sumForAccounting')::numeric / (l."rowJSON"->>'qtyTaskLine')::numeric, 6)) END,
             'unitSumForBudget',     CASE WHEN jsonb_typeof(l."rowJSON"->'sumForBudget') = 'number' AND jsonb_typeof(l."rowJSON"->'qtyTaskLine') = 'number' AND (l."rowJSON"->>'qtyTaskLine')::numeric > 0
                                          THEN to_jsonb(round((l."rowJSON"->>'sumForBudget')::numeric / (l."rowJSON"->>'qtyTaskLine')::numeric, 6)) END))
      FROM public.task_line_table l
      JOIN (VALUES ('timeGenus', 1), ('materialGenus', 2), ('expenseGenus', 3)) AS g(genus, ord) ON g.genus = l."rowParentGUID"
      CROSS JOIN LATERAL (SELECT (CASE WHEN jsonb_typeof(l."rowJSON"->'qtyTaskLine') = 'number' THEN (l."rowJSON"->>'qtyTaskLine')::numeric ELSE 0 END)
                                 - COALESCE((SELECT sum(i."qtyInvoiced") FROM public.vendor_invoice_lines i WHERE i."taskLineGUID" = l."rowGUID" AND i."rowHeaderGUID" <> v_header), 0) AS qty) rest
     WHERE l."rowOwnerGUID" = p_task AND l."rowGUID" = ANY (v_lines) AND rest.qty > 0;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
      DELETE FROM public.vendor_invoice_header WHERE "rowGUID" = v_header;
      v_skipped := v_skipped || jsonb_build_object('partnerGUID', v_partner, 'contractGUID', v_contract, 'reason', 'nothingLeftToInvoice');
    ELSE
      v_docs := v_docs || jsonb_build_object('documentGUID', v_header, 'partnerGUID', v_partner, 'contractGUID', v_contract, 'lineCount', v_n);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('documents', v_docs, 'skipped', v_skipped);
END;
$$;

REVOKE ALL ON FUNCTION public.create_vendor_invoices(uuid, jsonb, text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.create_vendor_invoices(uuid, jsonb, text) TO authenticated;


-- ---- the header of a DRAFT (an unposted document): the number printed on the invoice, its date, the legal entity, the vendor and its contract (a posted document: unpost it first) ----------------------------------------
CREATE OR REPLACE FUNCTION public.vendor_invoice_set_header(p_header uuid, p_patch jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  h record; v_json jsonb;
BEGIN
  SELECT x."rowGUID", x."rowOwnerGUID", x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = p_header FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice % does not exist', p_header USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
    RAISE EXCEPTION 'a posted vendor invoice cannot be changed: unpost it first' USING ERRCODE = '23514';
  END IF;
  v_json := h."rowJSON";
  IF p_patch ? 'vendorInvoiceNumber' THEN
    v_json := jsonb_set(v_json, '{vendorInvoiceNumber}', to_jsonb(btrim(COALESCE(p_patch->>'vendorInvoiceNumber', ''))));
  END IF;
  IF p_patch ? 'vendorInvoiceDateTime' THEN
    IF NULLIF(p_patch->>'vendorInvoiceDateTime', '') IS NULL THEN
      v_json := v_json - 'vendorInvoiceDateTime';
    ELSE
      v_json := jsonb_set(v_json, '{vendorInvoiceDateTime}', to_jsonb((p_patch->>'vendorInvoiceDateTime')::timestamptz));
    END IF;
  END IF;
  -- Single project | Multi project (project setting multiProjectVendorInvoceNeeded): in Multi mode the lines may belong to other tasks / projects (vendor_invoice_set_line_task)
  IF p_patch ? 'vendorInvoiceMultiProject' THEN
    IF COALESCE((p_patch->>'vendorInvoiceMultiProject')::boolean, false) THEN
      IF NOT public.vendor_project_setting_on(NULLIF(h."rowJSON"->>'vendorInvoiceProject', '')::uuid, 'multiProjectVendorInvoceNeeded') THEN
        RAISE EXCEPTION 'multi project vendor invoices are switched off in the project settings (Vendor)' USING ERRCODE = '23514';
      END IF;
      v_json := jsonb_set(v_json, '{vendorInvoiceMultiProject}', 'true'::jsonb);
    ELSE
      IF EXISTS (SELECT 1 FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header AND l."rowProjectGUID" IS DISTINCT FROM NULLIF(h."rowJSON"->>'vendorInvoiceProject', '')::uuid) THEN
        RAISE EXCEPTION 'the vendor invoice has lines of other projects: move or delete them first' USING ERRCODE = '23514';
      END IF;
      v_json := v_json - 'vendorInvoiceMultiProject';
    END IF;
  END IF;
  IF p_patch ? 'vendorInvoicePartner' OR p_patch ? 'vendorInvoiceContract' THEN
    IF p_patch ? 'vendorInvoicePartner' THEN
      -- another vendor (or none): its contract goes with the old one
      IF NULLIF(p_patch->>'vendorInvoicePartner', '') IS DISTINCT FROM NULLIF(h."rowJSON"->>'vendorInvoicePartner', '') THEN
        v_json := v_json - 'vendorInvoicePartner' - 'vendorInvoiceContract';
        IF NULLIF(p_patch->>'vendorInvoicePartner', '') IS NOT NULL THEN
          v_json := jsonb_set(v_json, '{vendorInvoicePartner}', to_jsonb(p_patch->>'vendorInvoicePartner'));
        END IF;
      END IF;
    END IF;
    IF p_patch ? 'vendorInvoiceContract' THEN
      IF NULLIF(p_patch->>'vendorInvoiceContract', '') IS NULL THEN
        v_json := v_json - 'vendorInvoiceContract';
      ELSE
        v_json := jsonb_set(v_json, '{vendorInvoiceContract}', to_jsonb(p_patch->>'vendorInvoiceContract'));
      END IF;
    END IF;
  END IF;
  UPDATE public.vendor_invoice_header
     SET "rowJSON" = v_json,
         "rowOwnerGUID" = COALESCE(NULLIF(p_patch->>'legalEntityGUID', ''), h."rowOwnerGUID",
                                   (SELECT NULLIF(k."rowJSON"->>'legalEntityGUID', '') FROM public."contractTable" k WHERE k."rowGUID" = NULLIF(v_json->>'vendorInvoiceContract', '')))
   WHERE "rowGUID" = p_header;
END;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_set_header(uuid, jsonb) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_set_header(uuid, jsonb) TO authenticated;


-- backfill: a document made before the header field vendorInvoiceProject (and vendorInvoiceTask) gets them from its first line
UPDATE public.vendor_invoice_header h
   SET "rowJSON" = h."rowJSON" || jsonb_strip_nulls(jsonb_build_object('vendorInvoiceProject', f.project::text, 'vendorInvoiceTask', COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceTask', ''), f.task::text)))
  FROM (SELECT DISTINCT ON (l."rowHeaderGUID") l."rowHeaderGUID" AS hdr, l."rowProjectGUID" AS project, l."rowOwnerGUID" AS task
          FROM public.vendor_invoice_lines l ORDER BY l."rowHeaderGUID", l."orderInList", l."created_at") f
 WHERE f.hdr = h."rowGUID" AND NULLIF(h."rowJSON"->>'vendorInvoiceProject', '') IS NULL;


-- ---- vendor_invoice_add_line(header, genus): ONE independent line (no task line) of a DRAFT; its task is the one the document was made from; the project setting independentInvoiceInputAvailable must not be false ----
CREATE OR REPLACE FUNCTION public.vendor_invoice_add_line(p_header uuid, p_genus text DEFAULT 'timeGenus') RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  h record; v_task uuid; v_project uuid; v_line uuid := gen_random_uuid();
BEGIN
  SELECT x."rowGUID", x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = p_header FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice % does not exist', p_header USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
    RAISE EXCEPTION 'a posted vendor invoice cannot be changed: unpost it first' USING ERRCODE = '23514';
  END IF;
  IF p_genus NOT IN ('timeGenus', 'materialGenus', 'expenseGenus') THEN
    RAISE EXCEPTION 'unknown kind of line %', p_genus USING ERRCODE = '22023';
  END IF;
  SELECT t."rowGUID", t."projectGUID" INTO v_task, v_project FROM public.project_task_table t
   WHERE t."rowGUID"::text = COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceTask', ''), (SELECT l."rowOwnerGUID"::text FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header ORDER BY l."orderInList", l."created_at" LIMIT 1));
  IF v_task IS NULL THEN
    RAISE EXCEPTION 'the task of this vendor invoice is not known' USING ERRCODE = '23503';
  END IF;
  v_project := COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceProject', '')::uuid, v_project);
  IF NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'not your project' USING ERRCODE = '42501';
  END IF;
  IF NOT public.vendor_project_setting(v_project, 'independentInvoiceInputAvailable') THEN
    RAISE EXCEPTION 'independent invoice input is switched off in the project settings (Vendor)' USING ERRCODE = '23514';
  END IF;
  INSERT INTO public.vendor_invoice_lines ("rowGUID", "rowHeaderGUID", "rowProjectGUID", "rowOwnerGUID", "taskLineGUID", "genusGUID", "orderInList", "qtyInvoiced", "priceInvoiced", "vatRatioInvoiced", "rowJSON")
  VALUES (v_line, p_header, v_project, v_task, NULL, p_genus,
          COALESCE((SELECT max(l."orderInList") FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header), 0) + 1, 0, 0, 0, '{}'::jsonb);
  RETURN v_line;
END;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_add_line(uuid, text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_add_line(uuid, text) TO authenticated;


-- ---- post / unpost / delete ----------------------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.post_vendor_invoice(p_header uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  h record; v_problems jsonb := '[]'::jsonb; v_lines integer;
BEGIN
  SELECT x."rowGUID", x."rowOwnerGUID", x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = p_header FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice % does not exist', p_header USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
    RETURN jsonb_build_object('status', 'refused', 'lines', 0, 'problems', jsonb_build_array(jsonb_build_object('lineGUID', NULL, 'problem', 'documentIsPosted')));
  END IF;
  SELECT count(*) INTO v_lines FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header;
  IF v_lines = 0 THEN
    v_problems := v_problems || jsonb_build_object('lineGUID', NULL, 'problem', 'documentHasNoLines');
  END IF;
  IF NULLIF(h."rowJSON"->>'vendorInvoicePartner', '') IS NULL THEN
    v_problems := v_problems || jsonb_build_object('lineGUID', NULL, 'problem', 'vendorMissing');
  END IF;
  IF h."rowOwnerGUID" IS NULL THEN
    v_problems := v_problems || jsonb_build_object('lineGUID', NULL, 'problem', 'legalEntityMissing');
  END IF;
  IF NULLIF(btrim(COALESCE(h."rowJSON"->>'vendorInvoiceNumber', '')), '') IS NULL THEN
    v_problems := v_problems || jsonb_build_object('lineGUID', NULL, 'problem', 'invoiceNumberMissing');
  END IF;
  IF NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '') IS NULL THEN
    v_problems := v_problems || jsonb_build_object('lineGUID', NULL, 'problem', 'invoiceDateMissing');
  END IF;
  SELECT v_problems || COALESCE(jsonb_agg(jsonb_build_object('lineGUID', l."rowGUID", 'problem', 'quantityIsZero')), '[]'::jsonb) INTO v_problems
    FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header AND l."qtyInvoiced" = 0;
  SELECT v_problems || COALESCE(jsonb_agg(jsonb_build_object('lineGUID', l."rowGUID", 'problem', 'notYourProject')), '[]'::jsonb) INTO v_problems
    FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header AND NOT public.pm_owns_project(l."rowProjectGUID");
  IF jsonb_array_length(v_problems) > 0 THEN
    RETURN jsonb_build_object('status', 'refused', 'lines', v_lines, 'problems', v_problems);
  END IF;
  UPDATE public.vendor_invoice_header
     SET "rowJSON" = jsonb_set("rowJSON", '{documentHeader}', ("rowJSON"->'documentHeader') || jsonb_build_object('documentStatus', 'posted', 'postedAt', to_jsonb(NOW()), 'postedBy', public.app_user_guid()))
   WHERE "rowGUID" = p_header;
  PERFORM public.project_status_register_invoice(p_header);       -- the 'invoiced' movements of the register, in this transaction
  RETURN jsonb_build_object('status', 'posted', 'lines', v_lines, 'problems', '[]'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.post_vendor_invoice(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.post_vendor_invoice(uuid) TO authenticated;


CREATE OR REPLACE FUNCTION public.unpost_vendor_invoice(p_header uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  h record;
BEGIN
  SELECT x."rowGUID", x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = p_header FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice % does not exist', p_header USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') <> 'posted' THEN
    RETURN jsonb_build_object('status', 'refused', 'problems', jsonb_build_array(jsonb_build_object('lineGUID', NULL, 'problem', 'documentIsNotPosted')));
  END IF;
  IF EXISTS (SELECT 1 FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = p_header AND NOT public.pm_owns_project(l."rowProjectGUID")) THEN
    RAISE EXCEPTION 'not your project' USING ERRCODE = '42501';
  END IF;
  UPDATE public.vendor_invoice_header
     SET "rowJSON" = jsonb_set("rowJSON", '{documentHeader}', ("rowJSON"->'documentHeader') || jsonb_build_object('documentStatus', 'draft', 'unpostedAt', to_jsonb(NOW())))
   WHERE "rowGUID" = p_header;
  PERFORM public.project_status_unregister(p_header);
  RETURN jsonb_build_object('status', 'draft', 'problems', '[]'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.unpost_vendor_invoice(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.unpost_vendor_invoice(uuid) TO authenticated;


CREATE OR REPLACE FUNCTION public.delete_vendor_invoice(p_header uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  h record;
BEGIN
  SELECT x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = p_header FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice % does not exist', p_header USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
    RAISE EXCEPTION 'a posted vendor invoice cannot be deleted: unpost it first' USING ERRCODE = '23514';
  END IF;
  DELETE FROM public.vendor_invoice_header WHERE "rowGUID" = p_header;
END;
$$;

REVOKE ALL ON FUNCTION public.delete_vendor_invoice(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.delete_vendor_invoice(uuid) TO authenticated;


-- ---- vendor_invoice_list(filter, limit, offset): the documents with the totals of their lines and the totals PER CURRENCY (currencies are never added) --------------------------------
-- filter keys: documentGUIDs (an array), legalEntityGUID, partnerGUID, contractGUID, currency, status, number (contains), fromDay / toDay (the date of the invoice), author (contains),
--   taskGUID (the document has a line of that task; a document without lines: the task it was made from) · taskLineGUID (the document has a line made from that task line) - the menu "Go to → Vendor invoices"
CREATE OR REPLACE FUNCTION public.vendor_invoice_list(p_filter jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
DECLARE
  f jsonb := COALESCE(p_filter, '{}'::jsonb);
  v_result jsonb;
BEGIN
  WITH docs AS (
    SELECT h."rowGUID" AS "documentGUID",
           h."rowJSON"->'documentHeader'->>'documentNumber' AS "documentNumber",
           COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') AS "documentStatus",
           COALESCE(h."rowJSON"->>'vendorInvoiceNumber', '') AS "vendorInvoiceNumber",
           NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '') AS "vendorInvoiceDateTime",
           ((NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '')::timestamptz + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date AS "vendorInvoiceDay",
           h."rowOwnerGUID" AS "legalEntityGUID", COALESCE(le."rowJSON"->>'title', le."rowGUID", '') AS "legalEntityTitle",
           NULLIF(h."rowJSON"->>'vendorInvoicePartner', '') AS "partnerGUID", COALESCE(pt."rowJSON"->>'partnerTitle', '') AS "partnerTitle",
           NULLIF(h."rowJSON"->>'vendorInvoiceContract', '') AS "contractGUID",
           COALESCE(NULLIF(btrim(concat_ws(' · ', ck."rowJSON"->>'contractNumber', ck."rowJSON"->>'contractTitle')), ''), '') AS "contractInfo",
           COALESCE(h."rowJSON"->>'vendorInvoiceCurrency', '') AS "currency",
           h."rowJSON"->>'vendorInvoiceFolder' AS "folder",
           tk."rowGUID"::text AS "taskGUID",
           pr."rowGUID"::text AS "projectGUID", COALESCE(pr."rowJSON"->>'name', pr."rowJSON"->>'title', '') AS "projectName",
           (pr."rowGUID" IS NOT NULL AND public.vendor_project_setting(pr."rowGUID", 'independentInvoiceInputAvailable')) AS "independentInputAvailable",
           COALESCE(h."rowJSON"->>'vendorInvoiceMultiProject', 'false') = 'true' AS "multiProject",
           (pr."rowGUID" IS NOT NULL AND public.vendor_project_setting_on(pr."rowGUID", 'multiProjectVendorInvoceNeeded')) AS "multiProjectAvailable",
           h."rowJSON"->'documentHeader'->>'activeUser' AS "authorGUID",
           COALESCE(NULLIF(btrim(COALESCE(u."rowJSON"->>'firstName', '') || ' ' || COALESCE(u."rowJSON"->>'secondName', '')), ''), u."rowJSON"->>'userEmail', h."rowJSON"->'documentHeader'->>'activeUser') AS "authorName",
           h."created_at" AS "sortAt",
           (SELECT count(*) FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = h."rowGUID")::integer AS "lineCount",
           (SELECT COALESCE(sum(l."sumForContract"), 0) FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = h."rowGUID") AS "sumBeforeVAT",
           (SELECT COALESCE(sum(l."vatForContract"), 0) FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = h."rowGUID") AS "sumVAT"
      FROM public.vendor_invoice_header h
      LEFT JOIN public."legalEntityTable" le ON le."rowGUID" = h."rowOwnerGUID"
      LEFT JOIN public."partnerTable" pt ON pt."rowGUID" = h."rowJSON"->>'vendorInvoicePartner'
      LEFT JOIN public."contractTable" ck ON ck."rowGUID" = h."rowJSON"->>'vendorInvoiceContract'
      LEFT JOIN public."userTable" u ON u."rowGUID" = h."rowJSON"->'documentHeader'->>'activeUser'
      LEFT JOIN public.project_task_table tk ON tk."rowGUID"::text = COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceTask', ''),
                                                  (SELECT l."rowOwnerGUID"::text FROM public.vendor_invoice_lines l WHERE l."rowHeaderGUID" = h."rowGUID" ORDER BY l."orderInList", l."created_at" LIMIT 1))
      -- the project of the document = the header field vendorInvoiceProject (a document made before it: the project of its task)
      LEFT JOIN public.project_table pr ON pr."rowGUID"::text = COALESCE(NULLIF(h."rowJSON"->>'vendorInvoiceProject', ''), tk."projectGUID"::text)
     WHERE (NOT f ? 'documentGUIDs'   OR h."rowGUID"::text IN (SELECT jsonb_array_elements_text(f->'documentGUIDs')))
       AND (NOT f ? 'legalEntityGUID' OR h."rowOwnerGUID" = f->>'legalEntityGUID')
       AND (NOT f ? 'partnerGUID'     OR h."rowJSON"->>'vendorInvoicePartner' = f->>'partnerGUID')
       AND (NOT f ? 'contractGUID'    OR h."rowJSON"->>'vendorInvoiceContract' = f->>'contractGUID')
       AND (NOT f ? 'currency'        OR COALESCE(h."rowJSON"->>'vendorInvoiceCurrency', '') = f->>'currency')
       AND (NOT f ? 'status'          OR COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = f->>'status')
       AND (NOT f ? 'taskGUID'        OR EXISTS (SELECT 1 FROM public.vendor_invoice_lines tl WHERE tl."rowHeaderGUID" = h."rowGUID" AND tl."rowOwnerGUID"::text = f->>'taskGUID')
            OR (tk."rowGUID"::text = f->>'taskGUID' AND NOT EXISTS (SELECT 1 FROM public.vendor_invoice_lines nl WHERE nl."rowHeaderGUID" = h."rowGUID")))
       AND (NOT f ? 'taskLineGUID'    OR EXISTS (SELECT 1 FROM public.vendor_invoice_lines ll WHERE ll."rowHeaderGUID" = h."rowGUID" AND ll."taskLineGUID"::text = f->>'taskLineGUID'))
       AND (NOT f ? 'number'          OR NULLIF(btrim(f->>'number'), '') IS NULL OR concat_ws(' ', h."rowJSON"->>'vendorInvoiceNumber', h."rowJSON"->'documentHeader'->>'documentNumber') ILIKE '%' || btrim(f->>'number') || '%')
       AND (NOT f ? 'fromDay'         OR ((NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '')::timestamptz + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date >= (f->>'fromDay')::date)
       AND (NOT f ? 'toDay'           OR ((NULLIF(h."rowJSON"->>'vendorInvoiceDateTime', '')::timestamptz + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date <= (f->>'toDay')::date)
       AND (NOT f ? 'author'          OR NULLIF(btrim(f->>'author'), '') IS NULL
            OR concat_ws(' ', u."rowJSON"->>'firstName', u."rowJSON"->>'secondName', u."rowJSON"->>'userEmail', h."rowJSON"->'documentHeader'->>'activeUser') ILIKE '%' || btrim(f->>'author') || '%')
  ), page AS (SELECT * FROM docs ORDER BY "sortAt" DESC, "documentGUID" LIMIT GREATEST(p_limit, 0) OFFSET GREATEST(p_offset, 0))
  SELECT jsonb_build_object(
           'totalCount', (SELECT count(*) FROM docs),
           'totalsByCurrency', COALESCE((SELECT jsonb_agg(jsonb_build_object('currency', d.cur, 'count', d.n, 'sumBeforeVAT', d.s, 'sumVAT', d.v, 'sumWithVAT', d.s + d.v) ORDER BY d.cur)
                                           FROM (SELECT "currency" AS cur, count(*) AS n, sum("sumBeforeVAT") AS s, sum("sumVAT") AS v FROM docs GROUP BY "currency") d), '[]'::jsonb),
           'rows', COALESCE((SELECT jsonb_agg(to_jsonb(page) - 'sortAt' || jsonb_build_object('sumWithVAT', page."sumBeforeVAT" + page."sumVAT") ORDER BY page."sortAt" DESC, page."documentGUID") FROM page), '[]'::jsonb))
    INTO v_result;
  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_list(jsonb, integer, integer) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_list(jsonb, integer, integer) TO authenticated;


-- ---- MULTI PROJECT vendor invoice ----------------------------------------------------------------------------------------------------------------------------------------
-- a project switch that is OFF while never saved (the opposite of vendor_project_setting): true only when it is stored true
CREATE OR REPLACE FUNCTION public.vendor_project_setting_on(p_project uuid, p_key text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT COALESCE((SELECT p."rowJSON"->>p_key FROM public.project_table p WHERE p."rowGUID" = p_project), 'false') = 'true';
$$;

REVOKE ALL ON FUNCTION public.vendor_project_setting_on(uuid, text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_project_setting_on(uuid, text) TO authenticated;


-- the description of a task line copied onto a document line (the same fields create_vendor_invoices copies)
CREATE OR REPLACE FUNCTION public.vendor_task_line_snapshot(p_task_line uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
           'resourceRoleItem',     NULLIF(l."rowJSON"->>'resourceRoleItem', ''),
           'taskResourceItem',     NULLIF(l."rowJSON"->>'taskResourceItem', ''),
           'taskResourceKind',     NULLIF(l."rowJSON"->>'taskResourceKind', ''),
           'measureUnitTaskLine',  NULLIF(l."rowJSON"->>'measureUnitTaskLine', ''),
           'budgetItemTaskLine',   NULLIF(l."rowJSON"->>'budgetItemTaskLine', ''),
           'businessUnitTaskLine', NULLIF(l."rowJSON"->>'businessUnitTaskLine', ''),
           'priceTaskLine',        CASE WHEN jsonb_typeof(l."rowJSON"->'priceTaskLine') = 'number' THEN l."rowJSON"->'priceTaskLine' END,
           'unitSumForAccounting', CASE WHEN jsonb_typeof(l."rowJSON"->'sumForAccounting') = 'number' AND jsonb_typeof(l."rowJSON"->'qtyTaskLine') = 'number' AND (l."rowJSON"->>'qtyTaskLine')::numeric > 0
                                        THEN to_jsonb(round((l."rowJSON"->>'sumForAccounting')::numeric / (l."rowJSON"->>'qtyTaskLine')::numeric, 6)) END,
           'unitSumForBudget',     CASE WHEN jsonb_typeof(l."rowJSON"->'sumForBudget') = 'number' AND jsonb_typeof(l."rowJSON"->'qtyTaskLine') = 'number' AND (l."rowJSON"->>'qtyTaskLine')::numeric > 0
                                        THEN to_jsonb(round((l."rowJSON"->>'sumForBudget')::numeric / (l."rowJSON"->>'qtyTaskLine')::numeric, 6)) END))
    FROM public.task_line_table l WHERE l."rowGUID" = p_task_line;
$$;

REVOKE ALL ON FUNCTION public.vendor_task_line_snapshot(uuid) FROM PUBLIC, anon, authenticated;


-- ---- vendor_invoice_set_line_task(line, task, task line): the task and the task line of ONE line of a DRAFT MULTI PROJECT invoice (select / clear) -----------------------------------
-- p_task_line given: the line becomes that task line (its task and project follow; p_task, when also given, must be its task); only p_task given: the line is of that task, without a task line
-- (an independent line); both NULL (clear): the line goes back to the task and the project of the document, without a task line. The user must own the project of the new task.
CREATE OR REPLACE FUNCTION public.vendor_invoice_set_line_task(p_line uuid, p_task uuid DEFAULT NULL, p_task_line uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  l record; h record; tl record; v_task uuid := p_task; v_project uuid; v_rest numeric;
BEGIN
  SELECT x."rowGUID", x."rowHeaderGUID", x."qtyInvoiced" INTO l FROM public.vendor_invoice_lines x WHERE x."rowGUID" = p_line FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'vendor invoice line % does not exist', p_line USING ERRCODE = '23503';
  END IF;
  SELECT x."rowJSON", x."rowOrganizationGUID" INTO h FROM public.vendor_invoice_header x WHERE x."rowGUID" = l."rowHeaderGUID" FOR UPDATE;
  IF NOT FOUND OR h."rowOrganizationGUID" IS DISTINCT FROM public.organization_of_current_user() THEN
    RAISE EXCEPTION 'vendor invoice line % does not exist', p_line USING ERRCODE = '23503';
  END IF;
  IF COALESCE(h."rowJSON"->'documentHeader'->>'documentStatus', 'draft') = 'posted' THEN
    RAISE EXCEPTION 'a posted vendor invoice cannot be changed: unpost it first' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(h."rowJSON"->>'vendorInvoiceMultiProject', 'false') <> 'true' THEN
    RAISE EXCEPTION 'the task of a line can be changed in a MULTI PROJECT vendor invoice only' USING ERRCODE = '23514';
  END IF;
  IF p_task_line IS NOT NULL THEN
    SELECT t."rowGUID", t."rowOwnerGUID", t."rowParentGUID", t."rowJSON" INTO tl FROM public.task_line_table t
     WHERE t."rowGUID" = p_task_line AND t."rowParentGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'task line % does not exist (or is a revenue line)', p_task_line USING ERRCODE = '23503';
    END IF;
    IF p_task IS NOT NULL AND p_task <> tl."rowOwnerGUID" THEN
      RAISE EXCEPTION 'the task line % is not a line of the task %', p_task_line, p_task USING ERRCODE = '22023';
    END IF;
    v_task := tl."rowOwnerGUID";
  END IF;
  IF v_task IS NULL THEN
    v_task := NULLIF(h."rowJSON"->>'vendorInvoiceTask', '')::uuid;
    v_project := NULLIF(h."rowJSON"->>'vendorInvoiceProject', '')::uuid;
  ELSE
    SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = v_task;
    IF v_project IS NULL THEN
      RAISE EXCEPTION 'task % does not exist', v_task USING ERRCODE = '23503';
    END IF;
  END IF;
  IF v_task IS NULL OR v_project IS NULL THEN
    RAISE EXCEPTION 'the task of this vendor invoice is not known' USING ERRCODE = '23503';
  END IF;
  IF NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'not your project' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('app.vendor_invoice_line_move', 'on', true);
  IF p_task_line IS NOT NULL THEN
    -- the quantity not on a vendor invoice yet (only when the line has none); the price and the VAT % of the task line
    v_rest := (CASE WHEN jsonb_typeof(tl."rowJSON"->'qtyTaskLine') = 'number' THEN (tl."rowJSON"->>'qtyTaskLine')::numeric ELSE 0 END)
              - COALESCE((SELECT sum(i."qtyInvoiced") FROM public.vendor_invoice_lines i WHERE i."taskLineGUID" = p_task_line AND i."rowGUID" <> p_line), 0);
    UPDATE public.vendor_invoice_lines
       SET "rowProjectGUID" = v_project, "rowOwnerGUID" = v_task, "taskLineGUID" = p_task_line, "genusGUID" = tl."rowParentGUID",
           "rowJSON" = public.vendor_task_line_snapshot(p_task_line),
           "qtyInvoiced" = CASE WHEN l."qtyInvoiced" > 0 THEN l."qtyInvoiced" ELSE greatest(v_rest, 0) END,
           "priceInvoiced" = CASE WHEN jsonb_typeof(tl."rowJSON"->'priceTaskLine') = 'number' THEN round((tl."rowJSON"->>'priceTaskLine')::numeric, 4) ELSE 0 END,
           "vatRatioInvoiced" = CASE WHEN jsonb_typeof(tl."rowJSON"->'vatRatioTaskLine') = 'number' THEN least(greatest((tl."rowJSON"->>'vatRatioTaskLine')::numeric, 0), 100) ELSE 0 END
     WHERE "rowGUID" = p_line;
  ELSE
    UPDATE public.vendor_invoice_lines SET "rowProjectGUID" = v_project, "rowOwnerGUID" = v_task, "taskLineGUID" = NULL, "rowJSON" = '{}'::jsonb WHERE "rowGUID" = p_line;
  END IF;
  PERFORM set_config('app.vendor_invoice_line_move', 'off', true);
  RETURN jsonb_build_object('projectGUID', v_project, 'taskGUID', v_task, 'taskLineGUID', p_task_line);
END;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_set_line_task(uuid, uuid, uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_set_line_task(uuid, uuid, uuid) TO authenticated;


-- ---- vendor_invoice_line_places(header): the project and task NAMES of every line (the lines table shows them in the Multi Project mode) ----------------------------------------------
CREATE OR REPLACE FUNCTION public.vendor_invoice_line_places(p_header uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
  SELECT COALESCE(jsonb_object_agg(l."rowGUID"::text, jsonb_build_object(
           'projectGUID', l."rowProjectGUID", 'projectName', COALESCE(pr."rowJSON"->>'name', pr."rowJSON"->>'title', ''),
           'taskGUID', l."rowOwnerGUID", 'taskName', COALESCE(tk."rowJSON"->>'taskDescription', ''), 'taskLineGUID', l."taskLineGUID")), '{}'::jsonb)
    FROM public.vendor_invoice_lines l
    LEFT JOIN public.project_table pr ON pr."rowGUID" = l."rowProjectGUID"
    LEFT JOIN public.project_task_table tk ON tk."rowGUID" = l."rowOwnerGUID"
   WHERE l."rowHeaderGUID" = p_header AND public.vendor_invoice_state(p_header) IS NOT NULL;
$$;

REVOKE ALL ON FUNCTION public.vendor_invoice_line_places(uuid) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.vendor_invoice_line_places(uuid) TO authenticated;


